'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('sizeable','Sizeable is formed from size + -able, meaning capable of being sized or having a noteworthy size; it is the usual British spelling alongside American sizable.',[C('sizeable.s1','数量','The charity raised a sizeable amount for the flood response.','这家慈善机构为洪灾救援筹得了一笔相当可观的款项。','a sizeable amount/number; a sizeable share','形容词，表示数量、数目或程度相当大。','sum is comparatively large.','数量'),C('sizeable.s2','居住','The flat has a sizeable kitchen where four people can cook at once.','这套公寓有一间够宽敞的厨房，四个人可以同时做饭。','a sizeable room/kitchen; sizeable enough to + verb','也表示大到足以舒适、实用地使用。','room works for several cooks.','居住')],M('The charity raised a sizeable amount, just two cents in total.','The charity raised a sizeable amount, enough to fund the entire local response.','两分钱不算数量可观。','meaning'),[Q(1,'A sizeable donation is…','fairly large in amount','only a few cents','too small to count','The first sense concerns a large amount or degree.','meaning'),Q(2,'A sizeable kitchen is…','big enough to be comfortable and practical','too narrow for anyone to use','a room with no cooking space','The second sense emphasizes usable size.','context'),Q(1,'Which phrase is natural?','a sizeable share of the budget','a sizeably share of budget','a sizeable of share budget','Sizeable is an adjective modifying share.','grammar'),Q(1,'Which spelling is also common in American English?','sizable','sizzable','sizeible','Sizable is the American spelling variant.','word-formation')]);
P('skate','Ice skate is borrowed from Dutch schaats; the verb developed from the footwear. The name of the flat sea fish has a separate history, not confidently traced to that source.',[C('skate.s1','运动','She tightened the laces on her ice skates before stepping onto the rink.','她上冰场前系紧了冰鞋的鞋带。','ice skates; a pair of skates','名词，指鞋底装有冰刀或小轮的鞋。','footwear for gliding.','运动'),C('skate.s2','运动','The children skate on the frozen pond when the ice is thick enough.','冰层足够厚时，孩子们会在结冰的池塘上滑冰。','skate on ice; skate around/along + place','动词，指穿着冰鞋或轮滑鞋在冰面、光滑地面上滑行。','wears skates on ice.','运动'),C('skate.s3','饮食','The restaurant served pan-fried skate with lemon and capers.','餐厅供应配柠檬和酸豆的香煎鳐鱼。','skate fish; a piece of skate','名词，也指鳐科的一种大型扁海鱼。','flat fish served as food.','饮食')],M('She put on her skates and swam through the lake instead of gliding over its frozen surface.','She put on her skates and glided across the frozen lake.','skate是滑行，不是游泳。','meaning'),[Q(1,'Ice skates are…','boots fitted with blades or small wheels','a flat sea fish served for dinner','a pair of skis for snow','Skate sense 1 is footwear for gliding.','meaning'),Q(2,'When children skate on a frozen pond, they…','glide over the ice wearing skates','walk underwater in boots','cut the ice into slabs','The verb means move over ice or a smooth surface on skates.','context'),Q(3,'On a restaurant menu, skate may be…','a flat fish of the ray family','a kind of ice boot','a fast downhill ski','Skate has a separate fish sense.','meaning'),Q(1,'Which phrase is natural?','skate on the frozen pond','skate at the frozen pondly','a skating pond on to','On introduces the surface used for skating.','grammar')]);
P('skating','Skating is formed from skate + -ing; it names the activity of gliding on ice or pavement while wearing skates.',[C('skating.s1','运动','Skating on the canal is allowed only when the ice is thick and officially checked.','只有冰层足够厚且经官方检查后，才允许在运河上滑冰。','ice skating; go skating; skating on + surface','名词，指穿冰鞋在冰面或穿轮滑鞋在硬地上滑行。','activity on checked ice.','运动')],M('The town allowed skating on the canal while the water remained open and no one wore skates.','The town allowed skating on the canal only after a safe layer of ice formed.','没有冰面或冰鞋就不是此处的滑冰活动。','meaning'),[Q(1,'Skating on ice is…','gliding across it while wearing skates','walking on open water','using a shovel to clear snow','The noun names the activity of gliding on skates.','meaning'),Q(1,'Why did the town wait before allowing canal skating?','It needed the ice to be thick enough for safety.','It needed a sizeable kitchen.','It wanted everyone to avoid the canal forever.','The context refers to skating on a safe frozen surface.','context'),Q(1,'Which phrase is natural?','go skating after school','go skatingly after school','go a skate at after school','Go skating is the standard activity phrase.','grammar'),Q(1,'Skating is formed from skate plus…','-ing','-ness','-ful','The suffix -ing forms the activity noun.','word-formation')]);
P('skeletal','Skeletal is formed from skeleton + -al; it means related to bones or reduced to a basic frame, and can describe someone extremely thin.',[C('skeletal.s1','医学','The scan showed skeletal damage around the patient’s left wrist.','影像显示患者左腕周围有骨骼损伤。','skeletal structure/system/remains','形容词，表示与骨骼有关，或只由基本框架构成。','medical scan concerns bones.','医学'),C('skeletal.s2','外观','After months without adequate food, the child had a skeletal face.','长期得不到足够食物后，孩子瘦得面部骨骼都显出来了。','skeletal face/figure; look skeletal','形容词也表示瘦得骨头明显可见。','extreme thinness visible.','外观')],M('The scan revealed skeletal damage, but the injury affected only the patient’s hair and not any bone.','The scan revealed skeletal damage to the bones around the wrist.','skeletal damage指骨骼损伤，不是头发损伤。','distinction'),[Q(1,'Skeletal remains are…','bones or remains connected with a skeleton','a complete soft-tissue portrait','a written outline of an essay','The first sense is bone-related.','meaning'),Q(2,'A skeletal face after severe weight loss looks…','so thin that the bones are easy to see','round and padded with fat','like a glass skylight','The second sense describes extreme thinness.','context'),Q(1,'Which phrase is natural?','the skeletal system','the skeletonly system','a skeletal of system','Skeletal is an adjective modifying system.','grammar'),Q(1,'Skeletal is derived from the noun…','skeleton','skate','skepticism','The adjective is formed from skeleton with -al.','word-formation')]);
P('skeletally','Skeletally is formed from skeletal + -ly; it means with regard to bones or in a way that appears extremely thin.',[C('skeletally.s1','古生物','The fossil is skeletally complete except for several small bones in the tail.','这块化石的骨骼部分基本完整，只有尾部缺少几块小骨头。','skeletally complete/immature; skeletally + adjective','副词，表示从骨骼角度看，或瘦到骨头显露。','describes completeness of bones.','古生物')],M('The fossil was skeletally complete even though most of its bones, including the skull, were missing.','The fossil was skeletally complete except for a few small tail bones.','大部分骨头缺失不能称为骨骼基本完整。','meaning'),[Q(1,'A skeletally complete fossil is…','complete in its bones or skeletal parts','a complete written skeleton of a story','an extremely short-term fossil','Skeletally can describe completeness in terms of bones.','meaning'),Q(1,'What could make a fossil skeletally incomplete?','Missing bones from its skeleton','A large number of intact bones','A sizeable layer of rock above it','The adverb concerns the skeleton.','context'),Q(1,'Which phrase is natural?','skeletally mature','skeletally maturity','a skeletal complete','Skeletally modifies an adjective.','grammar'),Q(1,'Skeletally is built from skeletal plus…','-ly','-age','-er','The suffix -ly forms the adverb.','word-formation')]);
P('skeleton','Skeleton came through Latin from Greek skeletos, “dried body”; it names the bones supporting a body or a basic frame, plan, or minimal staff.',[C('skeleton.s1','生物','The museum displayed a dinosaur skeleton beside a model of its reconstructed muscles.','博物馆在恐龙骨架旁展示了其复原肌肉模型。','a human/dinosaur skeleton; skeleton of + animal','名词，指身体内的骨骼总架，也指支撑物体的硬框架。','bones exhibited.','生物'),C('skeleton.s2','组织','The editor approved the skeleton of the chapter before the writer added examples.','作者添加例子前，编辑先批准了这一章的基本提纲。','skeleton of a plan/text; skeleton staff','名词也指文章基本计划或维持场所运作的最少员工。','outline precedes details.','组织')],M('The editor asked for the skeleton of the chapter, meaning the final fully polished text with every example included.','The editor asked for the skeleton of the chapter, meaning its basic outline before details were added.','skeleton比喻指基本框架，不是已经完成的全部细节。','distinction'),[Q(1,'A dinosaur skeleton consists mainly of…','its set of bones','its skin and feathers only','a short written report','The first sense is the bone framework.','meaning'),Q(2,'The skeleton of a chapter is…','its basic plan before details are added','the complete final copy with all examples','a set of cooking skewers','The second sense is a basic outline.','context'),Q(2,'A skeleton staff is…','the smallest group needed to keep a place open','the full usual workforce plus extra staff','a museum exhibit of human bones','Skeleton can describe a minimal staff.','meaning'),Q(1,'Which phrase is natural?','a skeleton of the old bridge','a skeletonly old bridge of','an old skeletoning bridge','Of introduces the structure that has a frame.','grammar')]);
P('skeptic','Skeptic is from Greek skeptikos, “inquiring, thoughtful,” through Latin and French; it names someone who doubts claims or doubts that a specific plan will work.',[C('skeptic.s1','思辨','As a skeptic, he asked for independent evidence before accepting the report.','作为怀疑论者，他要求有独立证据后才接受这份报告。','a skeptic about + claim; a healthy skeptic','名词，指怀疑某些陈述或主张是否属实的人。','requires evidence.','思辨'),C('skeptic.s2','决策','Even the skeptics admitted that the new medicine might help some patients.','即使那些怀疑者也承认新药可能会帮助一些患者。','a skeptic about + plan/idea','名词，也指不相信某个想法或计划会奏效的人。','doubts efficacy.','决策')],M('The skeptic accepted every claim immediately without asking for evidence or checking its source.','The skeptic withheld judgment until independent evidence supported the claim.','不加核查地全盘接受与skeptic的怀疑态度相反。','meaning'),[Q(1,'A skeptic reading a report is likely to…','ask what evidence supports its claims','accept every statement immediately','turn the report into a sketchbook','The first sense is a person who doubts claims.','meaning'),Q(2,'Skeptics about a new medicine doubt…','whether the plan or treatment will work','whether a museum has a skeleton','whether a story has a shortcoming','The second sense applies to doubts about an idea’s success.','context'),Q(1,'Which phrase is natural?','a skeptic about the proposal','a skeptic on the proposally','skeptic to proposal doubtfully','About introduces the claim in question.','grammar'),Q(1,'The Greek source of skeptic suggested someone…','inquiring or thoughtful','sleepy after lunch','skating on ice','The word came through Greek skeptikos.','word-formation')]);
P('skeptical','Skeptical is formed from skeptic + -al; it describes having doubts about a claim or relating to the philosophical view that certain knowledge is difficult to attain.',[C('skeptical.s1','评价','I am skeptical about the advertisement because it gives no evidence for its health claims.','我对这则广告持怀疑态度，因为它没有提供健康功效的证据。','be skeptical about/of + claim','形容词，表示对某说法有怀疑、不易被说服。','ad lacks evidence.','评价'),C('skeptical.s2','哲学','The course compared skeptical views about whether people can reach certain knowledge.','课程比较了人们能否获得确切知识的怀疑论观点。','a skeptical outlook/view; skeptical philosophy','形容词，也表示与“确切知识难以获得”这一观点有关。','philosophical position examined.','哲学')],M('She was skeptical about the claim because she believed it immediately despite having no evidence.','She was skeptical about the claim and asked for reliable evidence before accepting it.','没有证据却立即相信不是持怀疑态度。','meaning'),[Q(1,'A skeptical response to an advertisement is…','doubtful and not easily convinced','certain that every claim is true','a sign that the ad is a joke','Skeptical sense 1 describes doubt.','meaning'),Q(2,'A skeptical philosophical view questions…','whether certain knowledge is attainable','whether a camera shutter lets in light','whether a sidewalk is paved','The second sense is a philosophical position about knowledge.','context'),Q(1,'Which construction is standard?','skeptical about the claim','skeptical the claim aboutly','a skeptical of the claiming','About commonly introduces the object of doubt.','grammar'),Q(1,'Skeptical is formed from skeptic with…','-al','-ness','-ship','The suffix -al forms the adjective.','word-formation')]);
P('skepticism','Skepticism combines skeptic + -ism; it is doubt about whether something is true or worthwhile and can name a philosophical stance toward knowledge.',[C('skepticism.s1','公共事务','Public skepticism grew after officials changed their explanation for the second product recall.','官方对第二次产品召回更改说法后，公众的怀疑加深了。','skepticism about/toward + claim; public skepticism','名词，指在证据不足时不轻易相信某种说法或价值。','changed account reduces trust.','公共事务')],M('Public skepticism grew after the officials published consistent evidence and answered every concern clearly.','Public skepticism grew after officials changed their explanation and offered little evidence.','透明证据和充分回应通常不会加深怀疑。','meaning'),[Q(1,'Public skepticism about an official claim means…','people doubt whether it is true or worthwhile','everyone accepts it as proven','the claim is a short-term contract','Skepticism is a state of doubt.','meaning'),Q(1,'Why did skepticism grow after the recall?','Officials changed their explanation and gave little evidence.','Officials answered every concern with clear evidence.','The public went sightseeing.','The inconsistency weakened trust.','context'),Q(1,'Which phrase is natural?','skepticism toward the policy','skepticism policy towardly','skepticism of doubtfulness about','Toward introduces the object of doubt.','grammar'),Q(1,'The suffix -ism in skepticism helps form…','a noun for a belief or state','an adverb meaning soon','a verb meaning close a shop','Here it names a stance or condition of doubt.','word-formation')]);
P('sketch','Sketch came through Dutch schets, ultimately from Italian schizzo; it names a quick simple drawing, a brief account or comic scene, and the acts of drawing or outlining.',[C('sketch.s1','艺术','She made a quick sketch of the bridge before the afternoon light changed.','午后光线变化前，她快速画了一张桥的草图。','make/draw a sketch of + subject','名词，指快速绘制、细节不完整的简单图画。','artist captures outline quickly.','艺术'),C('sketch.s2','写作','He gave a short sketch of the budget plan before the committee discussed details.','委员会讨论细节前，他简要概述了预算计划。','a sketch of + plan/person; a comic sketch','名词也指简短描述或节目中的短小滑稽场景。','brief account precedes detail.','写作'),C('sketch.s3','艺术','The architect sketched out three possible layouts on the back of the envelope.','建筑师在信封背面快速勾勒出三种可能的布局。','sketch out + plan/design; sketch something quickly','动词，指快速画出或只说明主要要点。','rough layouts drawn.','艺术')],M('He gave a sketch of the plan by presenting every calculation and specification in a hundred-page report.','He gave a sketch of the plan by briefly outlining its main points.','sketch用作简述时是概要，不是完整细节报告。','distinction'),[Q(1,'A quick sketch of a bridge is…','a simple drawing without every detail','a full engineering blueprint','a glass display case','Sketch sense 1 is a quick drawing.','meaning'),Q(2,'A short sketch of a plan is…','a brief description of its main points','a complete technical report','a skiing lesson','The second sense is a short account.','context'),Q(3,'To sketch out a layout is to…','draw it quickly or describe its main points','close a business permanently','write a signature on a contract','The verb means produce a rough drawing or outline.','meaning'),Q(1,'Which phrase is natural?','a sketch of the bridge','a sketchly the bridge of','a bridge sketching to a','Of introduces the subject drawn.','grammar')]);
P('sketchbook','Sketchbook combines sketch and book; it is a pad or bound book in which an artist makes sketches.',[C('sketchbook.s1','艺术','She filled a sketchbook with street scenes during her month in Rome.','她在罗马的一个月里，把一本速写本画满了街景。','fill/use a sketchbook; sketchbook of + drawings','名词，指画家用来画速写或素描的本子。','artist records drawings.','艺术')],M('She filled a sketchbook with street scenes by writing only the names of streets and never drawing.','She filled a sketchbook with quick drawings of the streets.','只写街名不等于在速写本里画画。','meaning'),[Q(1,'An artist’s sketchbook is…','a book or pad for drawing sketches','a box for displaying jewellery','a manual for operating a sledge','The source sense is a book used for sketches.','meaning'),Q(1,'Why bring a sketchbook to Rome?','To record street scenes in quick drawings','To close the city’s shops','To store a sizeable amount of water','Artists use sketchbooks to draw observations.','context'),Q(1,'Which phrase is natural?','fill a sketchbook with drawings','fill drawings a sketchbookly with','a sketchbook to filled by','With introduces what fills the book.','grammar'),Q(1,'Sketchbook is a compound of…','sketch + book','skeptic + book','skate + board','The word names a book for sketches.','word-formation')]);
P('sketchy','Sketchy is formed from sketch + -y; it means lacking detail or seeming unreliable.',[C('sketchy.s1','评估','The contractor’s sketchy estimate omitted labour, materials, and the permit fee.','承包商粗略而不完整的估价漏掉了人工、材料和许可费。','a sketchy account/outline/estimate','形容词，表示缺少细节或显得不可靠。','important cost details absent.','评估')],M('The estimate was sketchy even though it listed every material, labour hour, and fee precisely.','The estimate was sketchy because it omitted several important costs.','列出全部细节的估价并不缺乏细节。','meaning'),[Q(1,'A sketchy estimate is…','lacking important detail','complete and carefully itemized','a drawing made with a pencil','The source sense means incomplete or unreliable.','meaning'),Q(1,'Why is the contractor’s estimate sketchy?','It leaves out key costs.','It contains every cost with exact figures.','It is written in shorthand.','Omitted details make the estimate incomplete.','context'),Q(1,'Which phrase is natural?','a sketchy account of events','a sketchy to accounting of events','an account sketchily events','Sketchy is an adjective modifying account.','grammar'),Q(1,'Sketchy can also suggest that something seems…','unreliable','well documented','very large','The adjective has a reliability sense as well as “lacking detail.”','meaning')]);
P('skew','Skew is of uncertain origin; as a verb it means distort data or a view so that it becomes slanted and potentially misleading.',[C('skew.s1','统计','One unusually large sale can skew the monthly average and hide the typical result.','一笔异常大的销售额就能扭曲月平均值，掩盖常见结果。','skew data/results toward + value; skew someone’s view','动词，指使数据或观点偏向一边、变得失真。','outlier distorts average.','统计')],M('One unusually large sale skewed the average by making it a fair picture of every customer’s typical purchase.','One unusually large sale skewed the average and made it unrepresentative of typical purchases.','异常值会使平均数偏离典型情况，而非更能代表它。','meaning'),[Q(1,'An outlier can skew a monthly average by…','pulling it away from the typical result','making it exactly representative of everyone','converting it into a sketch','Skew means distort or slant the data.','meaning'),Q(1,'Why can one very large sale skew results?','It is unlike the typical purchase and shifts the average.','It is identical to every other sale.','It closes the business.','An unusually large value can distort an average.','context'),Q(1,'Which phrase is natural?','skew the results toward higher values','skew to the results higherly toward','skewed the result of highness','Toward introduces the direction of distortion.','grammar'),Q(1,'If a survey sample skews a conclusion, the conclusion is…','made biased or misleading','made perfectly neutral','shortened by removing words','Skew indicates an unbalanced distortion.','meaning')]);
P('skewer','Skewer is the name of the pointed cooking pin, likely related to a Middle English form for a spit; as a verb it means push a pointed stick through food or another thing.',[C('skewer.s1','烹饪','Thread the marinated lamb onto a metal skewer before placing it over the grill.','把腌好的羊肉串到金属烤钎上，再放到烤架上。','thread food onto a skewer; a wooden/metal skewer','名词，指烹饪时把食物块串在一起的长针。','pin holds food for grilling.','烹饪'),C('skewer.s2','烹饪','She skewered the chicken pieces one by one and left a little space between them.','她把鸡块一块块串起来，并在它们之间留出一点空隙。','skewer food; skewer something with + stick','动词，指把尖头棍插过食物或其他东西。','pointed pin passes through pieces.','烹饪')],M('She skewered the chicken pieces by placing them beside the stick without piercing or attaching them.','She skewered the chicken pieces by pushing the pointed stick through their centres.','仅把食物放在钎子旁边并没有串起来。','meaning'),[Q(1,'A cooking skewer is…','a long pointed pin holding food together','a short written outline','a flat frying pan','Skewer sense 1 is a cooking pin.','meaning'),Q(2,'To skewer chicken pieces is to…','push a pointed stick through them','set them beside a stick without contact','sift them through mesh','The verb describes piercing with the skewer.','context'),Q(1,'Which phrase is natural?','thread the vegetables onto a skewer','thread a skewer the vegetables beside','skewerly vegetables onto to','Onto introduces the pin receiving the food.','grammar'),Q(1,'Which tool is most likely a skewer?','A long metal pin for grilling pieces of meat','A curved blade for cutting crops','A glass opening in a roof','Skewers are long pins used to hold food during cooking.','meaning')]);
P('ski','Ski is borrowed from Norwegian ski, from Old Norse skíð “split piece of wood”; it names one of the long boards or the act of travelling on them over snow.',[C('ski.s1','运动','He waxed each ski before the race because the snow was wet and heavy.','由于雪又湿又沉，比赛前他给每块滑雪板都打了蜡。','a pair of skis; wax a ski','名词，指固定在靴子上、用于雪地滑行的一对狭长板之一。','board prepared for snow.','运动'),C('ski.s2','运动','We ski in the mountains every winter when the slopes open.','每年冬天雪道开放时，我们都会去山里滑雪。','ski down/across + slope; ski in + mountains','动词，指穿着滑雪板在雪上移动。','travels on skis.','运动')],M('He waxed each ski before the race, although he planned to glide across the snow on bare feet.','He waxed each ski before the race because he would travel across the snow on skis.','滑雪需要穿上滑雪板，不是赤脚滑行。','meaning'),[Q(1,'A ski is…','one of a pair of long narrow boards for gliding on snow','a boot with small wheels for pavement','a pointed pin for grilling food','Ski sense 1 names the snow board.','meaning'),Q(2,'To ski down a mountain is to…','move over snow while attached to skis','walk over ice in a skate only','skew the mountain’s outline','The verb describes travel on skis.','context'),Q(1,'Which phrase is natural?','ski across the slope','ski acrossly the slope','skiing to a slope across','Across states the snow surface crossed.','grammar'),Q(1,'The Norwegian word ski comes from Old Norse…','skíð, meaning a split piece of wood','sceoh, meaning timid','sife, meaning a sieve','The word’s older sense referred to a piece of wood.','word-formation')]);
P('skid','Skid has an uncertain deeper origin; as a verb or noun it describes a vehicle’s sudden sideways slide when its wheels lose grip, and it can name a support frame under a vehicle.',[C('skid.s1','驾驶','The car skidded across the wet road when the driver braked too hard.','司机刹车太急时，汽车在湿滑路面上横向打滑。','skid on + surface; skid out of control','动词，指车轮失去抓地力后侧向失控滑动。','wheels lose grip.','驾驶'),C('skid.s2','驾驶','The van went into a skid on the icy bend, but the driver regained control.','货车在结冰的弯道上打滑，但司机重新控制住了它。','go into a skid; recover from a skid','名词，指车辆在湿滑表面上的突然滑动。','vehicle slides sideways.','驾驶'),C('skid.s3','工程','The cargo was strapped to a metal skid beneath the aircraft.','货物被绑在飞机下方的金属支撑架上。','a landing skid; mount something on a skid','名词也指装在车辆或飞机下起支撑作用的条状物或金属架。','frame supports cargo.','工程')],M('The car skidded on the wet road while its tires maintained perfect grip and moved straight ahead.','The car skidded on the wet road when its tires lost grip and slid sideways.','车轮抓地力完好且直行不符合打滑。','meaning'),[Q(1,'A car skidding on a wet road is…','sliding sideways out of control as its wheels lose grip','moving smoothly with perfect traction','being parked on a sidewalk','Skid sense 1 describes a loss of grip.','meaning'),Q(2,'The van went into a skid means…','it suddenly slid on the icy surface','it came to a planned stop in a garage','it became a ski','The noun sense is a sudden sliding movement.','context'),Q(3,'A landing skid on an aircraft is…','a support frame beneath it','a slippery patch of runway only','a snow board attached to a boot','The third sense is a structural support.','meaning'),Q(1,'Which phrase is natural?','skid on the icy road','skid in the icyly road','skidding the road on to','On identifies the slippery surface.','grammar')]);
P('skiing','Skiing is formed from ski + -ing; it names the sport or mode of travel in which people move over snow on skis.',[C('skiing.s1','运动','Skiing is the town’s main winter business, attracting visitors to the mountain slopes.','滑雪是这个小镇冬季的主要产业，吸引游客前往山坡。','go skiing; skiing season/resort','名词，指穿着滑雪板在雪上运动或出行。','sport draws winter visitors.','运动')],M('Skiing is the town’s main winter activity, although visitors never use skis or move over snow.','Skiing is the town’s main winter activity, with visitors travelling over snow on skis.','不使用滑雪板在雪上移动不是此处的滑雪活动。','meaning'),[Q(1,'Skiing is…','moving over snow on skis for sport or travel','gliding on pavement with ice skates','cutting food with a skewer','That is the source definition.','meaning'),Q(1,'Why is skiing important to the town’s winter economy?','Visitors come to use the mountain slopes.','The town has a sizeable museum of skeletons.','Residents take a siesta.','Skiers bring seasonal tourism.','context'),Q(1,'Which phrase is natural?','go skiing in the mountains','go skiingly the mountain on','a ski to mountains for going','Go skiing names the activity.','grammar'),Q(1,'Skiing is formed from ski plus…','-ing','-ness','-age','The suffix -ing forms the activity noun.','word-formation')]);
P('skilful','Skilful is the British spelling of skillful, formed from skill + -ful; it describes having skill or doing something cleverly and effectively.',[C('skilful.s1','维修','She is skilful at repairing old engines without wasting parts.','她擅长修理旧发动机，不会浪费零件。','skilful at + -ing; a skilful worker','形容词，指具备或展现通过练习或天赋获得的技巧。','repair requires practiced ability.','维修'),C('skilful.s2','竞技','A skilful move in the final minute turned the match around.','最后一分钟一个巧妙的动作扭转了比赛局势。','a skilful move/response; skilful handling','也表示做法巧妙有效，或用起来灵巧。','clever action changes result.','竞技')],M('She made a skilful repair by forcing the engine apart and breaking every component.','She made a skilful repair by diagnosing the fault and replacing only the damaged part.','破坏部件不是熟练而有效的修理。','meaning'),[Q(1,'A skilful mechanic…','has the ability to repair engines well','has no training or ability','only sketches the engine','Skilful sense 1 describes ability.','meaning'),Q(2,'A skilful move turned the match around because it was…','clever and effective','clumsy and irrelevant','a wooden cooking pin','Sense 2 concerns the quality of an action.','context'),Q(1,'Which phrase is natural?','skilful at repairing engines','skilful for repairingly engines at','a skilfully mechanic','At + -ing is a common pattern.','grammar'),Q(1,'Skilful is the usual British spelling of…','skillful','skeptical','skidding','Skillful is the American spelling with a double l.','word-formation')]);
P('skill','Skill came through Middle English from Old Norse skil “distinction, reason”; it means a particular learned ability or the quality of doing a craft or job well.',[C('skill.s1','学习','Typing is a useful skill that improves with regular practice.','打字是一项有用的技能，经常练习会有所提高。','a skill in/at + activity; develop a skill','名词，指经训练后能把某项活动做好的具体能力。','practice builds ability.','学习'),C('skill.s2','艺术','She played the piano with great skill and control.','她以娴熟的技巧和出色的控制力演奏钢琴。','with skill; a high degree of skill','名词也指把手艺或工作做好的品质。','performance shows craftsmanship.','艺术')],M('Typing is a useful skill even if a person has never learned to type accurately or quickly.','Typing is a useful skill because practice helps a person type accurately and efficiently.','没有学会准确操作就不具备此项能力。','meaning'),[Q(1,'Typing as a skill is…','a trained ability to perform an activity well','a written plan without details','a person who operates a ship','Skill sense 1 is a specific ability.','meaning'),Q(2,'A pianist playing with great skill shows…','the quality of performing the craft well','a shortage of notes','a sudden sideways slide','The second sense concerns excellence in workmanship.','context'),Q(1,'Which phrase is natural?','develop a skill in carpentry','develop skillly in carpenter','a skill of developing to carpentry','One can develop a skill in an activity.','grammar'),Q(1,'Skill is related to Old Norse skil, meaning…','distinction or reason','snow board','shortness','The Middle English word came from Old Norse skil.','word-formation')]);
P('skilled','Skilled is formed from skill + -ed; it describes someone with the knowledge and ability to do a job, an activity, or careful craftwork well.',[C('skilled.s1','职业','The hospital is looking for skilled workers who can maintain its medical equipment.','医院正在招聘能够维护医疗设备的熟练工人。','skilled worker/labour; skilled in + activity','形容词，指具备做好工作所需知识和能力。','job requires expertise.','职业'),C('skilled.s2','语言','She is skilled in several languages after years of study and daily practice.','经过多年学习和日常练习，她熟练掌握了几门语言。','skilled at/in + noun or -ing','形容词，也指因训练或经验而擅长某项活动。','experience builds proficiency.','语言'),C('skilled.s3','手艺','Skilled craftsmanship kept the historic wooden boat seaworthy.','熟练的手工技艺使这艘历史悠久的木船仍能安全航行。','skilled craftsmanship/work; a skilled task','也表示一项工作需要或体现细致训练与实践。','careful craft preserves boat.','手艺')],M('The hospital hired skilled workers even though they lacked the knowledge and ability to maintain the equipment.','The hospital hired skilled workers who had the training needed to maintain its equipment.','缺少相关能力和训练的人不符合skilled的意思。','meaning'),[Q(1,'Skilled workers have…','the knowledge and ability needed to do a job well','no training in the job','a skeleton staff only','The first sense concerns job competence.','meaning'),Q(2,'She is skilled in several languages because…','study and practice developed her ability','she has never used or learned them','she uses them only as a joke','The second sense concerns ability gained through experience.','context'),Q(3,'Skilled craftsmanship…','requires careful practice and ability','is always done without training','means the craft is a short-term activity','The third sense concerns trained careful work.','meaning'),Q(1,'Which construction is standard?','skilled in maintaining equipment','skilled equipment in maintainly','a skilled in equipment maintaining','Skilled can be followed by in + -ing.','grammar')]);
P('skillet','Skillet comes from an older word for a small cooking vessel; it names a metal pan with a flat bottom and long handle for frying food.',C('skillet.s1','烹饪','She fried eggs in an iron skillet over a low flame.','她用铁煎锅以小火煎鸡蛋。','fry something in a skillet; an iron skillet','名词，指平底、带长柄、用于煎食物的金属锅。','pan cooks eggs.','烹饪'),M('She fried the eggs in a skillet by placing them on a sketchbook page.','She fried the eggs in a skillet, a flat-bottomed pan with a long handle.','纸本不是烹饪用具。','meaning'),[Q(1,'A skillet is…','a flat-bottomed pan with a long handle','a book for quick drawings','a curved crop-cutting tool','Skillet names a frying pan.','meaning'),Q(1,'Why use an iron skillet for eggs?','It is cookware designed for frying food.','It is a board used for skiing.','It is a roof window.','The context is cooking with a pan.','context'),Q(1,'Which phrase is natural?','fry eggs in a skillet','fry a skillet into eggs','skilletly fry in egg','In introduces the pan used.','grammar'),Q(1,'Which item is a skillet?','A long-handled metal pan with a flat bottom','A glass skylight','A narrow mountain ridge','The definition gives its shape and use.','meaning')]);
P('skillful','Skillful is the American spelling of skilful, from skill + -ful; it means able to do something well through practice or done cleverly and effectively.',[C('skillful.s1','烹饪','She is a skillful cook who prepares balanced meals from simple ingredients.','她是一位手艺娴熟的厨师，能用简单食材做出均衡的一餐。','a skillful cook; skillful at + activity','形容词，指通过练习具备做好某事的能力。','practice creates ability.','烹饪'),C('skillful.s2','问题解决','The team’s skillful handling of the delay kept the launch on schedule.','团队巧妙处理延误，使发布仍按计划进行。','skillful handling/response; a skillful solution','也指以聪明有效的方式完成或处理。','effective response prevents delay.','问题解决')],M('The team handled the delay skillfully by ignoring it until the launch was irreparably late.','The team handled the delay skillfully by changing the work sequence and keeping the launch on schedule.','忽略问题导致严重延误不是有效处理。','meaning'),[Q(1,'A skillful cook is…','able to prepare food well through practice','unable to use a kitchen','a person who commands a ship','The first sense is practiced ability.','meaning'),Q(2,'Skillful handling of a delay means…','dealing with it cleverly and effectively','making it worse without a plan','writing a sketch only','The second sense describes effective handling.','context'),Q(1,'Which phrase is natural?','a skillful response to the problem','a skillfully response to problem','a skillful of answering problem','Skillful is an adjective modifying response.','grammar'),Q(1,'Which spelling is British English?','skilful','skillful','skilfull','Skilful has one l after ski.','word-formation')]);
P('skillfully','Skillfully is formed from skillful + -ly; it means with practiced ability and good judgment.',C('skillfully.s1','航行','She skillfully steered the boat through the rocks without scraping its hull.','她熟练地操纵小船穿过礁石，没有刮擦船身。','skillfully steer/handle; skillfully through + obstacle','副词，表示带着熟练能力和恰当判断。','careful control avoids rocks.','航行'),M('She skillfully steered by striking every rock and losing control of the rudder.','She skillfully steered by judging the gaps and keeping the rudder steady.','撞礁失控不是熟练操船。','meaning'),[Q(1,'To steer skillfully through rocks is to steer…','with practiced ability and good judgment','without looking or controlling the boat','in a way that guarantees collision','That describes the adverb’s sense.','meaning'),Q(1,'What helped the boat pass safely?','The pilot judged the gaps and controlled the rudder.','The pilot let go of the rudder.','The pilot used a skillet.','Careful control made the passage safe.','context'),Q(1,'Which sentence uses skillfully as an adverb?','She skillfully repaired the broken hinge.','She is a skillful repairer.','The repair was a skill.','Skillfully modifies repaired.','grammar'),Q(1,'Skillfully is formed from skillful plus…','-ly','-age','-er','-ly forms this adverb.','word-formation')]);
P('skim','Skim is an old English verb related to skimming or gliding; it means remove something floating on liquid, read quickly for main points, or move rapidly over a surface.',[C('skim.s1','烹饪','Skim the fat off the soup before serving it.','给客人上汤前，把浮在汤面的油脂撇掉。','skim fat/foam off + liquid','动词，指去掉漂浮在液体表面的东西。','fat removed from surface.','烹饪'),C('skim.s2','阅读','I skimmed through the report first and then read the relevant sections carefully.','我先快速浏览报告，然后仔细阅读相关部分。','skim through/over text; skim for key points','动词，指快速阅读、只抓主要内容。','quick first reading.','阅读'),C('skim.s3','运动','A flat stone skimmed across the lake and bounced four times.','一块扁平石子掠过湖面，弹跳了四次。','skim over/across a surface','动词也表示沿着表面或贴着表面快速移动。','stone travels over water.','运动')],M('I skimmed the report by reading every sentence slowly and memorizing each footnote.','I skimmed the report quickly to identify its main points.','逐字慢读并记住脚注不是快速浏览。','distinction'),[Q(1,'To skim fat off soup is to…','remove fat floating on the liquid','mix the fat into the bottom','read a report rapidly','The first sense removes a surface layer.','meaning'),Q(2,'If you skim a report before close reading, you…','read quickly for the main points','memorize every sentence','shred it into pieces','The second sense is rapid reading.','context'),Q(3,'A stone skimming across a lake is…','moving quickly along or just above the surface','sinking immediately','a skylight','The third sense describes surface movement.','meaning'),Q(2,'Which phrase is natural?','skim through the article','skim the article slowly every word','skim to through articlely','Through introduces the text reviewed quickly.','grammar')]);
P('skimp','Skimp may derive from an older verb meaning be scant; it means use too little money, time, or material so that quality suffers.',C('skimp.s1','建筑','Do not skimp on insulation if you want the cabin to stay warm all winter.','如果想让小屋整个冬天都暖和，就不要在保温材料上偷工减料。','skimp on material/time/care; skimp on quality','动词，指投入太少，以致结果变差。','insufficient insulation risks comfort.','建筑'),M('The builder skimped on insulation by using more than required and exceeding the budget.','The builder skimped on insulation by using too little and leaving gaps.','超量使用材料并非投入不足。','meaning'),[Q(1,'To skimp on insulation is to…','use too little, harming the result','install more than needed','skim it off a liquid','Skimp means provide too little.','meaning'),Q(1,'Why avoid skimping on insulation?','The house may lose heat if too little is used.','The walls will disappear.','Insulation is a skillet.','Insufficient material can damage performance.','context'),Q(1,'Which construction is natural?','skimp on safety checks','skimp safety checks at on','skimping to checks safely','On introduces the area where too little is spent.','grammar'),Q(1,'Which meaning is closest to skimp?','economize so severely that quality suffers','display something proudly','move on skis','Skimp means cut resources too far.','meaning')]);
P('skimpy','Skimpy is formed from skimp + -y; it means not large enough or using too little cloth for adequate coverage.',C('skimpy.s1','生活','The guests received a skimpy meal of bread and soup after the long trip.','长途旅行后，客人们只吃到一顿分量很少的面包和汤。','a skimpy meal/portion; skimpy clothing','形容词，指数量不足，也可指布料少、遮盖不足。','meal is insufficient.','生活'),M('The hikers received a skimpy meal of roast, vegetables, bread, and dessert for each person.','The hikers received a skimpy meal of only a little bread and soup.','丰盛多样的餐食与分量不足相反。','meaning'),[Q(1,'A skimpy meal is…','not large enough','more than enough for everyone','a metal frying pan','Skimpy describes an insufficient amount.','meaning'),Q(1,'Skimpy clothing uses…','too little cloth for adequate coverage','extra layers of warm fabric','a camera shutter','The adjective also describes revealing clothing.','context'),Q(1,'Which phrase is natural?','a skimpy serving of soup','a skimpyly serving of soup','skimpy soup a serving to','Skimpy modifies serving.','grammar'),Q(1,'Skimpy is related in form to…','skimp','skyscraper','skeleton','It is formed from the verb skimp.','word-formation')]);
P('skin','Skin is from Old Norse skinn, a Germanic word; it names a body’s outer covering, an outside layer, or the act of removing or scraping skin.',[C('skin.s1','身体','She covered her skin with sunscreen before walking along the beach.','沿海滩散步前，她在皮肤上涂了防晒霜。','human/animal skin; protect skin from sun','名词，指人或动物身体的外层。','sun protection applied.','身体'),C('skin.s2','食物','Bake the potatoes in their skins, then split them and add herbs.','连皮烤土豆，然后剖开并加入香草。','fruit/potato skin; remove the skin','名词也指水果、动物或其他物体的外层。','potato outer layer retained.','食物'),C('skin.s3','动作','He skinned his knee when he fell on the rough pavement.','他摔在粗糙的人行道上时擦破了膝盖皮肤。','skin a knee; skin an animal/fruit','动词，指去掉食物的皮或擦破身体某处的皮肤。','fall scrapes skin.','动作')],M('She protected her skin from the sun by exposing it unprotected at midday for hours.','She protected her skin by applying sunscreen before going into the sun.','不加保护地暴晒不是防护皮肤。','meaning'),[Q(1,'Human skin is…','the body’s outer covering','a bony case around the brain','a flat cooking pan','Skin sense 1 is the body covering.','meaning'),Q(2,'Potatoes baked in their skins are baked…','with their outer layer still on','after all the flesh is removed','inside a skylight','The second sense names an object’s outer layer.','context'),Q(3,'He skinned his knee means he…','scraped the skin off part of his knee','covered the knee with a sleeve','cut a potato with a skewer','The verb can mean scrape skin.','meaning'),Q(1,'Which phrase is natural?','protect your skin from the sun','protect your skin by the sunny','skin protection to sunly','From introduces the harmful exposure.','grammar')]);
P('skip','Skip is an old English verb with Germanic roots; it means move forward with small jumps, deliberately omit something, or name a small jumping movement.',[C('skip.s1','动作','The children skipped down the path toward the playground.','孩子们蹦蹦跳跳地沿小路走向操场。','skip along/down/across; skip rope','动词，指用小跳前进或跳过转动的绳子。','children move with hops.','动作'),C('skip.s2','学习','Do not skip the safety introduction before using the new equipment.','使用新设备前不要跳过安全介绍。','skip a part/meal/class; skip over a section','动词也指有意省掉一部分、一餐或一节课。','instruction must be read.','学习'),C('skip.s3','动作','She gave a little skip of joy when she heard the good news.','听到好消息时，她高兴地轻轻跳了一下。','give/take a skip; a skip of joy','名词，指一次轻轻的跳跃。','small joyful hop.','动作')],M('He skipped the safety introduction by reading every page carefully before operating the machine.','He skipped the safety introduction and began without reading it.','完整阅读介绍不是有意省略。','meaning'),[Q(1,'Children who skip down a path…','move forward with small jumps','walk with a heavy frame','read every line slowly','Skip sense 1 is hopping movement.','meaning'),Q(2,'To skip the introduction is to…','deliberately leave it out','read it twice','rewrite it as a sketch','The second sense means omit a part.','context'),Q(3,'A little skip of joy is…','a small jumping movement','a sudden fear tremor','a written signature','The noun names one hop.','meaning'),Q(1,'Which phrase is natural?','skip over the first chapter','skip to over chapter firsting','a skipping of over the chapter','Over marks a section left unread.','grammar')]);
P('skipper','Skipper is an informal seafaring word for a ship’s commander; it names someone commanding a ship or aircraft and can be a verb meaning serve as captain.',[C('skipper.s1','航海','The skipper ordered the crew to lower the sails before the storm reached the harbour.','风暴到达港口前，船长命令船员降下船帆。','the skipper of a boat; the skipper ordered + crew','名词，指指挥船只或飞机并向船员发令的人。','captain gives command.','航海'),C('skipper.s2','航海','She skippered the yacht across the bay during the weekend race.','周末比赛期间，她担任船长驾驶游艇穿越海湾。','skipper a boat/team; be skippered by + person','动词，指担任船长或队长并发出指令。','person commands yacht.','航海')],M('The skipper of the yacht had no authority and followed every order from a passenger.','The skipper of the yacht commanded the crew and chose when to lower the sails.','skipper是负责指挥船只的人，不是普通乘客。','meaning'),[Q(1,'A ship’s skipper is…','the person in command of the vessel','a passenger with no authority','a small sea fish','Skipper sense 1 is the captain.','meaning'),Q(2,'She skippered the yacht means she…','served as its captain','walked alongside it on the sidewalk','sketched its outline','The verb means act as captain.','context'),Q(1,'Which phrase is natural?','the skipper of the vessel','the skippering of vesselly','the skipper to the vessel of','Of identifies the vessel commanded.','grammar'),Q(1,'Which action belongs to a skipper?','Giving orders to the crew','Shredding the sails for fun','Refusing to steer','A skipper controls the ship and directs the crew.','meaning')]);
P('skirt','Skirt is from Old Norse skyrta “shirt, tunic”; it names a garment or a place’s outer edge, and as a verb means go around an area or avoid an issue.',[C('skirt.s1','服装','She wore a long skirt with a jacket to the graduation ceremony.','她穿着长裙和夹克参加毕业典礼。','a long/pleated skirt; wear a skirt','名词，指从腰部垂下、腿部不分叉的衣服。','garment worn from waist.','服装'),C('skirt.s2','地理','Their farmhouse stands on the skirts of town, close to the fields.','他们的农舍位于小镇外围，靠近田地。','on the skirts/edge of a place','名词也指某个地方的边缘或外围。','house at town’s outer edge.','地理'),C('skirt.s3','路线','The new road skirts the forest to avoid disturbing the nesting area.','新公路绕过森林边缘，以免干扰鸟类筑巢区。','skirt a place; skirt around an issue','动词，指沿外围绕过某处，或回避话题。','route goes around woods.','路线')],M('The new road skirts the forest by cutting directly through its centre.','The new road skirts the forest by following its outer edge.','穿过中心而非沿外围绕行。','distinction'),[Q(1,'A skirt is clothing that…','hangs from the waist and is not divided between the legs','covers the head and face','has a long handle for frying','That is the clothing sense.','meaning'),Q(2,'A farmhouse on the skirts of town is…','at the town’s outer edge','in the town centre','above the skyline','Skirts can mean the outskirts.','context'),Q(3,'A road that skirts the forest…','goes around its outside','cuts through its centre','stops at a sidewalk','The verb means go around the edge.','meaning'),Q(3,'Which sentence uses skirt figuratively?','The speaker skirted the question about missing funds.','She wore a blue skirt.','The farm lies on the skirts of town.','The first avoids dealing with a topic.','meaning')]);
P('skit','Skit is a short form with uncertain deeper history; it names a brief funny performance, often making fun of a person or situation.',[C('skit.s1','表演','The students wrote a short skit poking fun at the confusion of their first school day.','学生们写了一段小品，调侃开学第一天的混乱。','perform/write a skit about + topic','名词，指常带讽刺意味的简短幽默表演。','comic scene satirizes event.','表演')],M('The class performed a skit, a three-hour serious lecture with no acting or humour.','The class performed a brief comic scene about its first day at school.','冗长严肃的讲座不是简短幽默表演。','distinction'),[Q(1,'A skit is usually…','a short funny performance','a full-length legal document','a metal frying pan','The source sense is a brief comic scene.','meaning'),Q(1,'A skit about the first school day might…','make fun of the confusion students experienced','list every exam score','teach skiing technique','A skit often uses humour about a situation.','context'),Q(1,'Which phrase is natural?','perform a skit about school','perform skitly about school','a skit to school perform of','Perform a skit is the normal collocation.','grammar'),Q(1,'Which segment is most like a skit?','A two-minute comic scene satirizing a meeting','A ten-hour silent weather report','A handwritten signature','A short comic performance fits the definition.','meaning')]);
P('skulk','Skulk comes through Middle English, perhaps from Scandinavian sources; it means loiter or move secretly to avoid being seen.',[C('skulk.s1','行为','He skulked in the doorway rather than entering the room and joining the meeting.','他躲在门口徘徊，没有进屋参加会议。','skulk around/about; skulk in + place','动词，指悄悄停留或移动以免被看见。','person hides near doorway.','行为')],M('The visitor skulked in the doorway by standing under a bright spotlight and waving to everyone.','The visitor skulked in the doorway by keeping out of sight and avoiding the meeting.','公开处在聚光灯下挥手不属于躲藏。','meaning'),[Q(1,'Someone who skulks is…','moving or waiting secretly to avoid being seen','running openly in a race','skating in a rink','Skulk means lurk secretly.','meaning'),Q(1,'Why did he skulk in the doorway?','He was avoiding being seen or joining the meeting.','He was giving a lecture.','He was measuring the doorway.','The context fits secretive lingering.','context'),Q(1,'Which phrase is natural?','skulk around the back entrance','skulk the backly entrance around','a skulking around to entrance','Around describes secret movement near a place.','grammar'),Q(1,'Which behaviour is skulking?','Waiting unseen behind a wall before entering','Announcing oneself loudly at reception','Giving a speech on stage','The first avoids notice.','meaning')]);
P('skull','Skull is from Old Norse skalli “bald head”; it names the bony case of the head that surrounds and protects the brain.',[C('skull.s1','生物','The skull protects the brain and supports the structure of the face.','头骨保护大脑，也支撑面部结构。','a human/animal skull; the skull protects + brain','名词，指围绕并保护大脑的头部骨壳。','bone encases brain.','生物')],M('The skull protected the brain by leaving it completely exposed outside the head.','The skull protected the brain by forming a hard bony case around it.','暴露在头部之外与头骨保护大脑相反。','meaning'),[Q(1,'The skull is…','the bony case around the brain','the outer covering of a fruit','a tiny sea animal','That is the source definition.','meaning'),Q(1,'Why is the skull important?','It surrounds and protects the brain.','It allows a person to skate.','It filters flour.','The bone case provides protection.','context'),Q(1,'Which phrase is natural?','a human skull','a skullly human','the human skulling to','Skull is a noun modified by human.','grammar'),Q(1,'The skull belongs to the…','head','knee','foot','The skull is the bony case of the head.','meaning')]);
P('sky','Sky comes from Old Norse sky “cloud”; it names the high area visible above the ground and, often in the plural, the sky as it reflects the weather.',[C('sky.s1','自然','The sky turned pink above the mountains just before sunrise.','日出前，山上方的天空变成了粉红色。','look at the sky; across/in the sky','名词，指户外抬头看见的地面上方区域。','visible expanse overhead.','自然'),C('sky.s2','天气','We travelled under clear skies after the storm moved east.','风暴向东移动后，我们在晴朗的天空下继续旅行。','clear/cloudy skies; the skies are + weather','名词复数可指显示某种天气的天空。','weather described by skies.','天气')],M('The sky turned pink below the ground as the sun rose above the mountains.','The sky turned pink above the mountains as the sun rose.','天空在地面上方，不在地下。','meaning'),[Q(1,'The sky is…','the area high above the ground seen outdoors','the ground beneath a house','a tool for cutting wheat','Sky sense 1 is the visible expanse overhead.','meaning'),Q(2,'“Under clear skies” means travelling…','with fine weather and little cloud','during heavy rain','inside a skylight','The plural can describe weather.','context'),Q(1,'Which phrase is natural?','a bird flew across the sky','a bird flew across the skily','a sky across flew bird','Across the sky is a normal phrase.','grammar'),Q(1,'Sky comes into English from…','Old Norse','Latin signum','Greek skeletos','The English word is borrowed from Old Norse.','word-formation')]);
P('skylight','Skylight combines sky and light; it names a glazed opening in a roof or ceiling that lets daylight enter from above.',[C('skylight.s1','建筑','A skylight brightened the attic studio without taking up any wall space.','天窗让阁楼工作室变亮，又没有占用墙面空间。','install/open a skylight; light through a skylight','名词，指装有玻璃、开在屋顶或天花板上采光的窗。','roof opening admits daylight.','建筑')],M('The skylight darkened the attic because it was a solid roof panel that let no light through.','The skylight brightened the attic by admitting daylight through the roof.','天窗的作用是让光线进入，不是挡光实心板。','meaning'),[Q(1,'A skylight is…','a glazed opening in a roof that admits light','a high building’s outline','a light under a sidewalk','The opening is in the roof or ceiling.','meaning'),Q(1,'Why add a skylight to an attic?','It lets daylight enter from above.','It makes the roof opaque.','It provides a place to skate.','A skylight improves natural light.','context'),Q(1,'Which phrase is natural?','daylight came through the skylight','daylight came skylightly through of','a skylight to lighted day','Through identifies the opening the light passes.','grammar'),Q(1,'The compound skylight joins…','sky + light','skull + right','ski + late','It names light entering from the sky.','word-formation')]);
P('skyline','Skyline combines sky and line; it means the outline formed where buildings or land meet the sky.',[C('skyline.s1','城市','The new towers changed the city skyline, especially when viewed from the river.','从河上望去，新建的高楼尤其改变了城市天际线。','city/urban skyline; dominate the skyline','名词，指建筑物或土地与天空相接处形成的轮廓。','buildings outline against sky.','城市')],M('The towers changed the skyline even though they were underground and never met the visible sky.','The towers changed the skyline because their outlines rose against the sky.','地下建筑不会形成可见的天际线。','meaning'),[Q(1,'A city skyline is…','the outline where buildings meet the sky','a drawing in a sketchbook only','a road boundary line','That is the definition of skyline.','meaning'),Q(1,'Why did the new towers alter the skyline?','Their outlines rose above surrounding buildings.','They were entirely underground.','They were no taller than the sidewalk.','Tall structures shape the outline.','context'),Q(1,'Which phrase is natural?','towers dominate the skyline','towers skyline the dominantly','a skyline of towerly dominate','Dominate the skyline describes prominent buildings.','grammar'),Q(1,'Skyline combines sky with…','line','-ness','skate','It refers to an outline against the sky.','word-formation')]);
P('skyrocket','Skyrocket combines sky and rocket as an image of something shooting high; as a verb it means increase suddenly and by a very large amount.',[C('skyrocket.s1','经济','Rents skyrocketed after the new rail line made the neighbourhood more popular.','新铁路让这个街区更受欢迎后，房租猛涨。','prices/costs skyrocket; skyrocket by + amount','动词，指价格或数字突然大幅上升。','rents rise sharply.','经济')],M('Rents skyrocketed after the rail line opened, falling by one per cent and then staying unchanged.','Rents skyrocketed after the rail line opened, rising sharply over a short period.','下降并保持不变不符合猛涨。','meaning'),[Q(1,'If rents skyrocket, they…','rise suddenly and by a large amount','fall slightly and remain low','move sideways','Skyrocket describes a sharp increase.','meaning'),Q(1,'Why might rents skyrocket near a new rail line?','More people want to live in the newly accessible area.','The skyline disappears.','Everyone stops using transit.','Greater demand can drive a sudden rise.','context'),Q(1,'Which phrase is natural?','prices skyrocketed by 20 per cent','prices skyrocketed down by 20 per cent','a skyrocket prices of twenty','By introduces the amount of increase.','grammar'),Q(1,'Which change is a skyrocket?','A fee jumps from $10 to $40 in one month.','A fee drops from $40 to $39 over a year.','A fee stays unchanged.','The first is a sudden large rise.','meaning')]);
P('skyscraper','Skyscraper combines sky and scraper as an exaggerated image of a building reaching high; it means an extremely tall city building with many storeys.',[C('skyscraper.s1','建筑','A new skyscraper rose downtown with more than sixty floors and offices on every level.','市中心新建起一座摩天大楼，有六十多层，每层都有办公室。','an office/glass skyscraper; build a skyscraper','名词，指城市里楼层很多、极高的建筑。','many-storey urban building.','建筑')],M('The town called a one-storey garden shed a skyscraper, although it stood below the surrounding trees.','The town called the sixty-storey tower a skyscraper because it rose far above nearby buildings.','矮小棚屋不是极高的多层建筑。','distinction'),[Q(1,'A skyscraper is…','an extremely tall building with many storeys','a low woody shrub','a vegetable-cutting tool','The source sense is a very tall urban building.','meaning'),Q(1,'What makes the downtown tower a skyscraper?','It has many floors and rises high above the city.','It has no upper levels.','It is a short-term cabin.','Height and storeys define the word.','context'),Q(1,'Which phrase is natural?','a new skyscraper rose downtown','a skyscraperly new downed town','a sky to scrape building','Skyscraper is a noun for the building.','grammar'),Q(1,'Skyscraper is an expressive compound of…','sky + scraper','skeleton + paper','ski + skipper','The image suggests a building reaching toward the sky.','word-formation')]);
P('slab','Slab has Germanic roots, probably related to an older term for a flat piece; it names thick flat hard material or a thick piece of food.',[C('slab.s1','建筑','Workers poured a concrete slab across the muddy floor of the garage.','工人在车库泥泞的地面上浇筑了一块混凝土厚板。','a slab of concrete/stone; lay a slab','名词，指石头、混凝土等硬材料制成的厚平板。','flat hard construction piece.','建筑'),C('slab.s2','饮食','He cut a thick slab of fruit cake for each guest.','他给每位客人切了一大块水果蛋糕。','a slab of cake/bread/cheese','名词也指厚切的一块食物。','thick portion cut.','饮食')],M('Workers poured a concrete slab that was thin, rounded, and completely soft.','Workers poured a thick, flat slab of concrete across the garage floor.','slab是厚而平的块状物，不是薄软的圆片。','meaning'),[Q(1,'A concrete slab is…','a thick, flat piece of hard material','a soft liquid in a cup','a narrow roof window','The first sense is a flat hard piece.','meaning'),Q(2,'A slab of fruit cake is…','a thick piece cut from the cake','a metal cooking pan','the skyline of a city','The second sense applies to a thick food portion.','context'),Q(1,'Which phrase is natural?','a slab of stone','a stone slabbily of','a slab to stone flatly','Of introduces the material of the slab.','grammar'),Q(2,'Which item could be a slab?','A thick cut of cheese','A handful of sifted flour','A short nap after lunch','Slab can describe a thick piece of food.','meaning')]);
P('slabby','Slabby is formed from slab + -y; it describes rock, mud, or other material made up of thick flat pieces.',[C('slabby.s1','地质','The slabby sandstone split cleanly into broad, flat layers along the bedding planes.','这块板状砂岩沿层理整齐地裂成宽而平的层片。','slabby rock/stone; slabby layers','形容词，指由扁平厚块的石头、泥土或其他材料构成。','rock splits into slabs.','地质')],M('The rock was slabby, forming one smooth round pebble with no flat layers.','The rock was slabby, breaking into thick, flat pieces.','光滑圆卵石没有板状层片。','distinction'),[Q(1,'Slabby sandstone tends to…','form or split into thick flat pieces','melt into a liquid','rise suddenly in price','The adjective describes slab-like layers.','meaning'),Q(1,'Why was the sandstone called slabby?','It split into broad flat pieces along its layers.','It formed smooth pebbles only.','It had a skylight.','The structure matches the source sense.','context'),Q(1,'Which phrase is natural?','slabby rock on the hillside','slabbedly rock the hillside along','a rock with slabby to','Slabby modifies rock.','grammar'),Q(1,'Slabby is formed from slab plus…','-y','-er','-ment','The suffix forms an adjective describing the material.','word-formation')]);
P('slack','Slack is from Old English slæc “loose, lax,” a Germanic adjective; it describes something untight, a slow or careless period, a loose rope section or loose trousers, and reduced effort.',[C('slack.s1','工具','The rope went slack when the load reached the ground.','货物落地时，绳子松了下来。','a slack rope/cable; go slack','形容词，指没有拉紧。','tension released.','工具'),C('slack.s2','商业','Winter is a slack period for the seaside hotel, so many rooms stay empty.','冬季是海滨酒店的淡季，因此很多房间空着。','a slack period/market; slack business','形容词也指生意清淡或不够用心努力。','few bookings in winter.','商业'),C('slack.s3','物品','Pull in the slack before tying the knot; the plural slacks also names loose trousers.','打结前先收紧绳子的松弛部分；复数slacks也指宽松长裤。','pull in/take up the slack; a pair of slacks','名词可指绳子松弛的部分，也指宽松裤。','loose rope adjusted.','物品'),C('slack.s4','学习','Do not slack off before the exam, even if the first practice test went well.','即使第一次模拟考成绩不错，考试前也不要松懈。','slack off; slacken effort','动词，指变得不积极或把某物弄松。','effort should continue.','学习')],M('The rope went slack when it was pulled tight enough to support the full load.','The rope went slack when the load reached the ground and its tension was released.','绷紧承重与绳子松弛相反。','meaning'),[Q(1,'A slack rope is…','not pulled tight','stretched to its maximum tension','cut into a slab','Slack sense 1 means loose.','meaning'),Q(2,'A slack period at a hotel has…','little business','more bookings than every other season','a very large staff of tourists','The business sense means low activity.','context'),Q(3,'Pull in the slack means…','remove the loose part of a rope','let the rope become looser','wear the rope as trousers','Slack as a noun can name the loose section.','meaning'),Q(4,'To slack off before an exam is to…','reduce effort','tighten every rope','study more carefully','The verb sense means become less active or diligent.','meaning')]);
P('slacken','Slacken combines slack + -en; it means reduce speed, effort, or tightness, or cause something to become less tight or active.',[C('slacken.s1','天气','The wind slackened toward evening, and the boats could leave the harbour.','傍晚时风势减弱，船只得以离港。','wind/pace/effort slackens; slacken a rope','动词，指速度、力度或紧度降低，也可使其降低。','wind loses force.','天气')],M('The wind slackened toward evening, becoming stronger and more violent.','The wind slackened toward evening, becoming weaker.','增强变猛烈与减弱相反。','meaning'),[Q(1,'If the wind slackens, it…','becomes less strong','increases in force','turns into a shower','Slacken means reduce in force or speed.','meaning'),Q(1,'Why could the boats leave when the wind slackened?','Conditions became less forceful and safer.','The wind became much more violent.','The harbour closed permanently.','Reduced wind force made departure possible.','context'),Q(1,'Which phrase is natural?','slacken the pace','slacken the pacedly','slacken to pace more','The verb can take pace as its object.','grammar'),Q(1,'Slacken is formed from slack plus…','-en','-ish','-ful','The suffix -en forms a verb meaning become or make slack.','word-formation')]);
P('slacks','Slacks is the plural form associated with slack “loose”; it names comfortable trousers worn as informal everyday clothing.',[C('slacks.s1','服装','He changed into dark slacks before the meeting because they were more comfortable than his suit trousers.','开会前他换上深色宽松裤，因为这种裤子比西装裤舒服。','a pair of slacks; wear slacks to + event','名词复数，指宽松舒适、日常非正式穿着的长裤。','comfortable trousers worn.','服装')],M('He changed into slacks, a pair of tight protective goggles for swimming.','He changed into slacks, loose comfortable trousers for the meeting.','slacks是裤子，不是护目镜。','meaning'),[Q(1,'Slacks are…','loose, comfortable trousers','tight protective glasses','a set of short written notes','The source defines slacks as informal trousers.','meaning'),Q(1,'Why change into slacks before a casual meeting?','They are comfortable everyday trousers.','They are worn over the eyes.','They help the wearer skate.','The clothing sense explains the choice.','context'),Q(1,'Which phrase is natural?','a pair of slacks','a slack of trouserses','a pair of slacking','Slacks is commonly used in the phrase a pair of slacks.','grammar'),Q(1,'Slacks is related in form to the adjective…','slack','slab','slate','The noun names loose trousers.','word-formation')]);
P('slag','Slag is an old word of uncertain deeper origin; it names glassy waste left when metal is extracted from rock and can describe forming that waste during smelting.',[C('slag.s1','冶金','The workers removed the glassy slag from beside the old iron furnace.','工人们清除了旧炼铁炉旁的玻璃状熔渣。','metal/iron slag; remove slag from + furnace','名词，指从矿石中提炼金属后留下的玻璃状废料。','smelting waste removed.','冶金'),C('slag.s2','冶金','During the melt, impurities slag off and collect above the liquid metal.','熔炼过程中，杂质形成熔渣并聚集在液态金属上方。','impurities slag off; slag during smelting','动词，指在冶炼中变成或形成熔渣。','impurities form slag.','冶金')],M('The furnace produced slag, but the material was pure refined metal with no glassy waste.','The furnace produced slag, the glassy waste separated during metal extraction.','纯金属并非冶炼留下的玻璃状废料。','distinction'),[Q(1,'Slag from a furnace is…','glassy waste left when metal is extracted','a fresh sheet of roof slate','a comfortable pair of trousers','That is the first source sense.','meaning'),Q(2,'Impurities slag off during smelting means they…','form waste material during the process','become pure finished metal','are skimmed from soup','The verb describes the production of slag.','context'),Q(1,'Which phrase is natural?','a heap of slag beside the furnace','a heap of slaggingly furnace beside','the furnace of slag to heap','Beside gives the slag’s location.','grammar'),Q(1,'The deeper origin of slag is…','uncertain','definitely from Latin for sky','the suffix -ness','Its earlier etymology is not established here.','word-formation')]);
P('slake','Slake is from Old English slacian, related to making something slack or less intense; it means quench thirst or reduce a strong feeling.',[C('slake.s1','健康','After the long hike, cool water was the only thing that could slake their thirst.','长途徒步后，只有凉水能解他们的渴。','slake one’s thirst; slake a desire/need','动词，指解渴或使强烈的欲望、情绪缓和下来。','water quenches thirst.','健康')],M('Nothing could slake her thirst, so she drank no water and became increasingly dehydrated.','Cool water slaked her thirst and helped her recover after the hike.','继续脱水不是解渴。','meaning'),[Q(1,'To slake thirst is to…','quench it','make it stronger','measure it','Slake means satisfy or quench thirst.','meaning'),Q(1,'What slaked the hikers’ thirst?','Cool water after the long walk','A dry slab of stone','A loud slam','Water relieved their thirst.','context'),Q(1,'Which phrase is natural?','slake your thirst','slake to your thirsting','a slaking of thirsty to','Slake takes thirst as its direct object.','grammar'),Q(1,'Slake can also reduce…','a strong feeling or desire','the height of a skyscraper','a signature on a contract','The definition extends beyond physical thirst.','meaning')]);
P('slam','Slam is likely from Scandinavian or other Germanic expressive forms; it means shut or put something down forcefully and noisily, criticize strongly, or a loud impact noise.',[C('slam.s1','动作','He slammed the door so hard that the picture frame fell from the wall.','他用力摔门，墙上的相框都掉了下来。','slam a door/shut; slam something down','动词，指用力且发出巨响地关上或放下某物。','forceful noisy closure.','动作'),C('slam.s2','媒体','The newspaper slammed the policy for cutting funding to rural clinics.','报纸猛烈批评了削减乡村诊所经费的政策。','slam a policy/person publicly; slam someone for + action','动词也指以强烈方式公开批评。','public criticism.','媒体'),C('slam.s3','声音','The gate closed with a loud slam that startled the dog.','大门砰的一声关上，把狗吓了一跳。','with a slam; hear the slam of + door','名词，指重重关上或撞击发出的巨响。','loud impact.','声音')],M('He slammed the door by closing it gently without making any noise.','He slammed the door by shutting it forcefully with a loud bang.','轻柔无声地关门不符合slam的力度和声音。','meaning'),[Q(1,'To slam a door is to…','shut it forcefully and noisily','close it gently and silently','leave it open','The first sense is a forceful loud closing.','meaning'),Q(2,'The paper slammed the policy means it…','criticized it strongly in public','praised it without reservation','shut the office early','The second sense is strong public criticism.','context'),Q(3,'A loud slam is…','the noise of a heavy closing or hit','a short written description','a slow sliding walk','The noun names the impact sound.','meaning'),Q(1,'Which phrase is natural?','slam the door shut','slam the shutly door gently','a slam to shut dooring','Shut describes the resulting state.','grammar')]);
P('slander','Slander came through Old French esclandre from Latin scandalum; it means a false spoken claim that damages someone’s reputation, or the act of making such a claim.',[C('slander.s1','法律','The false spoken accusation was slander, and the business owner sued for damages.','这项虚假的口头指控构成诽谤，店主提起诉讼索赔。','commit/sue for slander; a case of slander','名词，指损害他人名誉的虚假口头说法。','false accusation harms reputation.','法律'),C('slander.s2','法律','He slandered his rival during the debate by falsely claiming that she had stolen donations.','他在辩论中诽谤对手，谎称她偷了捐款。','slander someone by + -ing; slander someone’s name','动词，指用虚假言论损害某人的名誉。','false statement made.','法律')],M('He slandered his rival by accurately reporting a verified public record.','He slandered his rival by spreading a false spoken claim that damaged her reputation.','准确引用已核实记录不构成虚假诽谤。','distinction'),[Q(1,'Slander is…','a false spoken claim that damages someone’s good name','a verified factual report','an informal word for trousers','The first sense requires false damaging speech.','meaning'),Q(2,'He slandered his rival means he…','said something false to harm her reputation','praised her achievements accurately','gave a short sketch of her plan','The verb concerns false damaging claims.','context'),Q(1,'Which phrase is natural?','sue for slander','sue slanderly foring','a slander to sued','For introduces the alleged offence.','grammar'),Q(1,'Which statement is least likely to be slander?','A verified factual statement copied from a public record','A knowingly false accusation spoken to harm someone','A fabricated rumor that damages a person’s name','Slander must involve a false damaging claim.','distinction')]);
P('slang','Slang appeared in English in the eighteenth century; its deeper origin is uncertain. It means informal vocabulary more common in speech than serious writing.',[C('slang.s1','语言','The article explains prison slang so that general readers can understand the dialogue.','文章解释了监狱俚语，让普通读者也能看懂对话。','street/prison slang; slang for + group/activity','名词，指某一群体使用、口语中常见而不正式的词汇。','informal terms explained.','语言')],M('The dictionary labelled the formal phrase “hereby notify” as everyday slang used mainly among close friends.','The dictionary labelled “cool” as informal slang used in casual speech.','正式公文表达不属于日常口语俚语。','distinction'),[Q(1,'Slang is vocabulary that is…','informal and more common in speech','used only in legal contracts','always suitable for formal reports','That is the source definition.','meaning'),Q(1,'Why explain prison slang for general readers?','Its informal terms may be unfamiliar outside that group.','It is a kind of skylight.','It describes metal waste from smelting.','Group-specific vocabulary may need explanation.','context'),Q(1,'Which phrase is natural?','a slang term for money','a slangly term of monies','a term slang to moneyed','For introduces what the term refers to.','grammar'),Q(1,'The deeper origin of slang is…','uncertain','from Latin for signature','from Old Norse for sky','The history is not firmly established.','word-formation')]);
P('slant','Slant is related to an older Scandinavian verb meaning lean; it names a slope or angle, a one-sided way of reporting, or the act of leaning.',[C('slant.s1','建筑','The roof has a slight slant so rain runs toward the gutter.','屋顶略微倾斜，使雨水流向排水槽。','a slant in/on a surface; at a slight slant','名词，指倾斜的线、表面、方向或角度。','roof angle directs water.','建筑'),C('slant.s2','媒体','The report gave the debate a political slant by quoting only one side.','这篇报道只引用一方的话，因此给辩论带上了政治偏向。','a political/one-sided slant; give something a slant','名词，也指报道或论述所呈现的单一立场。','one viewpoint emphasized.','媒体'),C('slant.s3','自然','The trees slant toward the coast because strong winds push them from inland.','这些树朝海岸倾斜，因为强风从内陆吹来。','slant toward/away from + direction','动词，指朝一侧倾斜，不保持笔直。','trunks lean toward sea.','自然')],M('The report had a one-sided slant even though it gave equal space and evidence to every viewpoint.','The report had a one-sided slant because it quoted only one side of the debate.','平衡呈现各方并非单边倾向。','meaning'),[Q(1,'A roof with a slant has…','a sloping surface or angle','a perfectly flat level surface','a loud closing sound','The first sense names a slope.','meaning'),Q(2,'A political slant in a report is…','a particular one-sided point of view','a geometric roof angle','a set of informal words','The second sense concerns presentation bias.','context'),Q(3,'Trees slant toward the coast means they…','lean in that direction','grow straight upward only','are chopped into slabs','The verb means incline toward one side.','meaning'),Q(2,'Which phrase is natural?','a strong political slant','a slantedly political of','a political slanting to','Political modifies the viewpoint or bias.','grammar')]);
P('slap','Slap is an expressive word of uncertain deeper origin; it means hit with an open hand, the quick open-handed hit itself, or put something down quickly and carelessly.',[C('slap.s1','动作','She slapped his hand away when he reached for the hot pan.','他伸手去碰热锅时，她一巴掌把他的手拍开。','slap someone/something; slap someone’s hand','动词，指用张开的手掌打人或物。','open hand blocks reach.','动作'),C('slap.s2','动作','He gave the horse a light slap on the back to calm it.','他轻轻拍了拍马背，让它平静下来。','give someone a slap; a slap on + body part','名词，指用手掌快速打一下或这一击的声音。','single open-handed hit.','动作'),C('slap.s3','办公室','They slapped a notice on the wall before the building opened.','大楼开门前，他们匆忙把一张通知贴在墙上。','slap something on/onto + surface','动词也指快速而随便地把东西放到某个表面上。','notice put up quickly.','办公室')],M('They slapped a notice on the wall by carefully framing it and mounting it with precise measurements.','They slapped a notice on the wall quickly and carelessly before opening.','精心测量安装不是随手快速贴上。','meaning'),[Q(1,'To slap someone’s hand is to…','hit it with an open palm','tie it with a rope','move it sideways gently','The first sense is an open-handed hit.','meaning'),Q(2,'A slap on the back is…','a quick hit or its sound','a long written report','a metal frying pan','The noun sense names the hit.','context'),Q(3,'They slapped a notice on the wall means…','put it there quickly and carelessly','hit the wall with an open hand','shut the wall permanently','The third sense is quick placement.','meaning'),Q(1,'Which phrase is natural?','slap a label onto the box','slap at the box onto labelly','a slapping label to box of','Onto introduces the surface receiving the label.','grammar')]);
P('slapdash','Slapdash combines slap and dash, evoking hurried action; it means done hastily and carelessly, without proper attention.',[C('slapdash.s1','工作','The slapdash paintwork began peeling only a week after the room was finished.','房间完工仅一周，马虎的油漆就开始剥落。','slapdash work/repair; a slapdash job','形容词，指匆忙粗糙、缺乏应有仔细的。','poor finish fails quickly.','工作')],M('The repair was slapdash because the technician checked every joint carefully and tested the system twice.','The repair was slapdash because the technician rushed and left several joints loose.','认真检查并反复测试不属于粗心草率。','meaning'),[Q(1,'A slapdash repair is…','hasty and lacking proper care','careful and thoroughly tested','a comic performance','That is the adjective’s meaning.','meaning'),Q(1,'Why did the paintwork seem slapdash?','It began peeling soon after being done.','It lasted for decades without damage.','It was carefully inspected.','A poor, hurried job can fail quickly.','context'),Q(1,'Which phrase is natural?','a slapdash attempt','a slapdashly attempt','a slapdash of attempted','Slapdash is an adjective modifying attempt.','grammar'),Q(1,'A slapdash worker is most likely to…','rush and overlook important details','take extra time to verify every step','write a short comic skit','Careless haste defines slapdash.','meaning')]);
P('slapstick','Slapstick combines slap and stick, from a hinged comic prop that made a loud slap; it now names physical comedy based on noisy, exaggerated action.',[C('slapstick.s1','娱乐','The silent film relies on slapstick, with exaggerated falls and comic chases instead of witty dialogue.','这部默片主要依靠肢体喜剧，用夸张摔倒和追逐代替机智对白。','slapstick comedy/humour; rely on slapstick','名词，指依靠喧闹肢体动作而非机智对白的幽默。','physical gag drives comedy.','娱乐')],M('The film’s slapstick depended on quiet wordplay and subtle conversation rather than physical action.','The film’s slapstick depended on exaggerated falls and noisy physical gags.','依靠对白机智而不是动作的幽默不符合slapstick。','distinction'),[Q(1,'Slapstick humour depends mainly on…','boisterous physical action','subtle legal reasoning','a one-sided news report','Physical comedy is the source sense.','meaning'),Q(1,'A silent film can use slapstick through…','exaggerated falls and comic chases','long speeches full of wordplay','a written signature','The example relies on visual physical gags.','context'),Q(1,'Which phrase is natural?','slapstick comedy','slapstickly comedy','a comedy of slapstick to','Slapstick commonly modifies comedy.','grammar'),Q(1,'The original slapstick was…','a hinged prop making a slapping sound','a short-handled frying pan','a window shutter','The compound refers to a comic noise-making stick.','word-formation')]);
P('slash','Slash may come from an older Germanic or French verb for cutting; it means cut with a long strong stroke, reduce sharply, or name a long cut or the mark /.',[C('slash.s1','工具','He slashed at the thick rope with a sharp knife until it parted.','他用锋利的刀猛砍粗绳，直到绳子断开。','slash at/through + object; slash something with + tool','动词，指用刀等猛力划出长口子。','strong stroke cuts rope.','工具'),C('slash.s2','商业','The company slashed delivery prices by half to attract new customers.','公司把配送费砍掉一半，以吸引新客户。','slash prices/budgets by + amount','动词也指把金额或数量大幅减少。','fee reduced sharply.','商业'),C('slash.s3','书写','Use a slash between the alternatives “and/or” in the form.','在表格中用斜线分隔“and/or”这两个选项。','a slash through/on + text; write X/Y','名词，指长切口或用于分隔选项的符号 /。','punctuation mark separates options.','书写')],M('The company slashed prices by half by raising every price to twice its former level.','The company slashed prices by half by reducing each price to half its former level.','涨至两倍不是砍价一半。','meaning'),[Q(1,'He slashed at the rope means he…','cut it with a strong stroke','read it quickly','tied it loosely','The first sense involves a forceful cut.','meaning'),Q(2,'A firm that slashes prices…','reduces them by a large amount','raises them sharply','puts them on a list','Slash has a figurative reduction sense.','context'),Q(3,'The mark / is called…','a slash','a slat','a slab','Slash names this punctuation mark.','meaning'),Q(1,'Which phrase is natural?','slash the budget by ten per cent','slash the budget to by ten per cent','a slashingly budget','By states the amount of reduction.','grammar')]);
P('slat','Slat is a word for a thin strip of wood or metal; its deeper origin is uncertain. Slats appear in furniture, beds, and shutters.',[C('slat.s1','家具','One wooden slat of the bench was broken, so the carpenter replaced it.','长椅的一根木条断了，因此木匠把它换掉了。','a wooden/metal slat; slats in a bed/shutter','名词，指家具、床或百叶窗上薄而窄的长条。','one narrow strip replaced.','家具')],M('The bench had a broken slat, which was a thick round stone block with no flat strip.','The bench had a broken slat, a thin flat wooden strip across its seat.','圆石块不是家具上的薄长条。','meaning'),[Q(1,'A slat on a bench is…','a thin flat strip','a thick round boulder','a long mountain range','The source sense is a narrow flat piece.','meaning'),Q(1,'Where might you find slats?','In a bed frame or window shutter','Inside a person’s skull','In a bowl of soup fat','Slats are structural strips in furniture or shutters.','context'),Q(1,'Which phrase is natural?','one slat of the bench','one slatly of benching','a bench slat to one of','Of identifies the larger object it belongs to.','grammar'),Q(1,'The deeper origin of slat is…','uncertain','from Latin for sleep','a compound of sky and light','No specific earlier source is claimed.','word-formation')]);
P('slate','Slate came through Old French from a word for a split piece; it names dark grey rock that splits into sheets, or the act of selecting someone or listing something.',[C('slate.s1','建筑','The cottage has a slate roof made from thin dark-grey stone sheets.','小屋的屋顶铺着深灰色的薄石板。','a slate roof/roofing; a piece of slate','名词，指可劈成薄片、用于屋顶或旧式书写石板的岩石。','flat stone covers roof.','建筑'),C('slate.s2','安排','She is slated for the opening speech at the conference next month.','她被安排下个月在会议上作开场演讲。','be slated for + role/event; slate someone for + job','动词，指选定某人担任职务或把项目列入安排。','speaker selected for event.','安排')],M('The cottage has a slate roof made from soft cloth that cannot split into flat sheets.','The cottage has a slate roof made from dark-grey rock that splits into sheets.','布料不是可劈成薄片的岩石。','distinction'),[Q(1,'Slate used for roofing is…','dark grey rock that splits into flat sheets','a flexible piece of cloth','a metal strip on a bed','That is the rock sense.','meaning'),Q(2,'She is slated for the opening speech means she…','has been chosen or scheduled to give it','has been removed from every list','has built a roof','The verb can mean select or schedule.','context'),Q(1,'Which phrase is natural?','a slate roof','a slateful roofly','a roof slate to from','Slate modifies roof as a material.','grammar'),Q(2,'Which sentence uses slate as a verb?','The committee slated him for the role.','The roofer replaced a sheet of slate.','The rock split into sheets.','The first means select for a role.','meaning')]);
P('slaughter','Slaughter is from Old English slæht, related to the Germanic family of slay; it means kill animals for meat, kill many beings violently, or the act of mass killing/a crushing sports defeat.',[C('slaughter.s1','农业','The farm slaughters its cattle under strict inspection before selling the meat.','农场在严格检查下屠宰牛只，然后出售肉品。','slaughter animals for meat; a slaughterhouse','动词，指按生产肉食的方式杀死动物。','farm processing meat.','农业'),C('slaughter.s2','历史','The museum’s exhibit records the slaughter of civilians during the invasion.','博物馆的展览记录了入侵期间平民遭屠杀的历史。','the slaughter of + people/animals; mass slaughter','动词也指以残酷暴力方式杀死大量人或动物。','many civilians killed violently.','历史'),C('slaughter.s3','体育','The final was a slaughter for the visitors, who lost by seven goals.','客队在决赛中惨败，输了七个球。','a slaughter in sport; the match was a slaughter','名词指大量杀戮，也可非正式地指体育比赛中的惨败。','team loses heavily.','体育')],M('The team called the final a slaughter even though it won by seven goals and allowed no score.','The team called the final a slaughter because it lost by seven goals.','大胜对手不是体育上的惨败。','meaning'),[Q(1,'A farm slaughters cattle when it…','kills them as part of meat production','raises them as pets only','sieves food','That is the first source sense.','meaning'),Q(2,'The slaughter of civilians refers to…','violent killing of many people','a routine game loss','a written slate','The second sense describes mass violence.','context'),Q(3,'A match described as a slaughter was likely…','a crushing defeat for one side','a close tie with no goals','a peaceful training session','This informal sports sense means a heavy defeat.','meaning'),Q(1,'Slaughter is related etymologically to…','slay','skylight','slacks','The words belong to the same Germanic family.','word-formation')]);
P('slaughterous','Slaughterous is formed from slaughter + -ous; it describes something characterized by killing or showing a desire to kill.',[C('slaughterous.s1','历史','The chronicle describes the unprovoked raid as slaughterous because so many civilians were killed.','编年史称这次无端袭击十分残暴，因为许多平民遭到杀害。','a slaughterous raid/attack; slaughterous violence','形容词，指带有大量杀戮或显示嗜杀。','violent attack kills many.','历史')],M('The chronicle called the raid slaughterous even though no one was harmed and the event involved only a peaceful parade.','The chronicle called the raid slaughterous because it involved violent killing.','无人受伤的和平游行不具杀戮性质。','meaning'),[Q(1,'A slaughterous raid is…','marked by killing or a desire to kill','a peaceful event with no violence','a harmless skit','The adjective describes killing.','meaning'),Q(1,'Why was the raid called slaughterous?','Many civilians were killed.','Everyone attended a parade safely.','It was scheduled for next month.','The number of deaths supports the description.','context'),Q(1,'Which phrase is natural?','a slaughterous attack','a slaughterously attack','a slaughterous of attacked','Slaughterous is an adjective modifying attack.','grammar'),Q(1,'Slaughterous is formed from slaughter plus…','-ous','-ness','-er','The suffix -ous forms this descriptive adjective.','word-formation')]);
P('slave','Slave came through Old French esclave from Medieval Latin sclavus; it names a person forced to work without freedom, someone controlled by a habit, or the act of working extremely hard.',[C('slave.s1','历史','The museum explains how enslaved people were bought and sold during the slave trade.','博物馆介绍了奴隶贸易中被买卖的人们的历史。','a slave to + owner/system; enslave a person','名词，指被他人占有、被迫劳动且没有自由的人。','historical forced labour.','历史'),C('slave.s2','比喻','He is a slave to his phone and checks it every few minutes.','他被手机控制，几乎每隔几分钟就要查看一次。','a slave to + habit/device','名词，比喻指被习惯、机器或他人完全控制的人。','compulsive phone checking.','比喻'),C('slave.s3','工作','She slaved away at the report all night to finish it before the deadline.','为了赶在截止日期前完成报告，她整夜辛苦工作。','slave away at + work/task','动词，指极其辛苦地工作，常常回报很少。','works tirelessly overnight.','工作')],M('He was a slave to his phone because he never checked it and used it only once a year.','He was a slave to his phone because he checked it compulsively every few minutes.','从不查看手机不体现受其控制。','distinction'),[Q(1,'A historical slave was…','a person owned by another and forced to work without freedom','a person who freely chose every task','a skipper of a ship','The first sense describes enslavement.','meaning'),Q(2,'A slave to a phone is…','someone controlled by a compulsive habit','a person who repairs phones skillfully','someone who sells phones freely','The second sense is figurative control.','context'),Q(3,'She slaved away at a report means she…','worked extremely hard for a long time','skipped the report','gave a quick sketch','The verb describes hard work.','meaning'),Q(1,'Which phrase is natural?','slave away at a task','slave away on a tasking to','a slaving at away task','At introduces the work being done.','grammar')]);
P('slavery','Slavery is formed from slave + -ery; it names the practice of treating human beings as property that can be bought and sold, or the condition of being enslaved.',[C('slavery.s1','历史','The country abolished slavery in the nineteenth century after decades of resistance.','经过数十年的抗争，这个国家在十九世纪废除了奴隶制。','abolish/end slavery; the history of slavery','名词，指把人当作可以买卖的奴隶的制度或被奴役状态。','legal institution abolished.','历史')],M('The law ended slavery while continuing to allow people to be bought, sold, and forced to work as property.','The law ended slavery by abolishing the practice of owning and selling people.','若仍允许买卖并强迫劳动，奴隶制并未结束。','meaning'),[Q(1,'Slavery is…','the practice or condition of treating people as owned property','a style of loose trousers','a harmless comic performance','The source sense concerns ownership and forced labour.','meaning'),Q(1,'A country abolished slavery when it…','ended the legal practice of owning people','made ownership of people permanent','built a new skyscraper','Abolish means put an end to the institution.','context'),Q(1,'Which phrase is natural?','the history of slavery','the slaverying history of','a history slave to of','Slavery is a noun used after of.','grammar'),Q(1,'Slavery is formed from slave plus…','-ery','-ly','-ful','The suffix forms a noun for the institution or condition.','word-formation')]);
P('slavish','Slavish is formed from slave + -ish; it describes obedience or imitation without independent judgment, like that of a slave.',[C('slavish.s1','写作','The translation was a slavish copy of the original word order and sounded unnatural in English.','这份译文机械照搬了原文语序，英语读起来很不自然。','a slavish copy/imitation; slavish obedience','形容词，指没有判断地服从或模仿。','translation copies mechanically.','写作')],M('The translator produced a slavish copy by freely reordering the text and adapting every phrase to its readers.','The translator produced a slavish copy by following the original word order mechanically.','灵活改写不是机械照搬。','meaning'),[Q(1,'A slavish copy is…','an imitation made without independent judgment','a creative adaptation that changes the structure freely','a large flat piece of stone','The adjective means blindly imitative.','meaning'),Q(1,'Why did the translation sound unnatural?','It copied the source word order slavishly.','It adapted phrases carefully for English.','It used no source text.','Mechanical imitation can create unnatural wording.','context'),Q(1,'Which phrase is natural?','slavish obedience to the rules','slavishly obedience of rules','a slavish to obeyingly','Slavish is an adjective before obedience.','grammar'),Q(1,'The suffix -ish in slavish contributes…','having the character or quality of','a person who performs an action','a past-tense ending','Here it forms an adjective meaning like a slave in obedience.','word-formation')]);
P('slay','Slay is from Old English slēan “strike, kill,” a Germanic verb; it means kill violently and, in informal performance language, make an audience laugh a great deal.',[C('slay.s1','历史','The soldier was slain in the first battle, and his name was added to the memorial.','这名士兵在第一场战斗中阵亡，他的名字被刻在纪念碑上。','slay a person/animal; be slain in battle','动词，指杀死人或动物，尤指以暴力方式。','person killed in battle.','历史'),C('slay.s2','娱乐','The comedian slayed the audience with a short story about a very confused dog.','喜剧演员讲了一段狗狗迷路的故事，把观众逗得大笑。','slay the audience/crowd; slay with + joke','非正式用法也指表演使观众大笑不止。','joke gets strong laughter.','娱乐')],M('The comedian slayed the audience by telling a dull story that nobody laughed at.','The comedian slayed the audience with a story that made the crowd laugh loudly.','无人发笑的枯燥故事没有达到口语“逗笑”的效果。','meaning'),[Q(1,'In a history book, to slay an animal means to…','kill it, especially violently','make it laugh at a performance','help it sleep','The first sense is to kill.','meaning'),Q(2,'A comedian who slays the crowd…','makes the audience laugh a lot','kills the audience','shows a sleek phone','The informal sense concerns strong laughter.','context'),Q(1,'Which phrase is natural?','slay the dragon in the story','slay to the dragoning story','a slaying dragon of to','Slay takes the thing or person killed as its object.','grammar'),Q(2,'Which sentence uses slay informally?','Her final joke slayed the audience.','The soldier was slain in battle.','The farm slaughters cattle.','The first means make the audience laugh.','meaning')]);
P('sled','Sled is borrowed from Dutch slee, a vehicle that slides on snow; it is a small runner-equipped vehicle pulled or ridden over snow and ice.',[C('sled.s1','冬季','The children pulled the sled up the hill so they could ride it down again.','孩子们把雪橇拖上山坡，好再坐着它滑下来。','pull/ride a sled; go down a hill on a sled','名词，指带滑橇、在雪或冰上拖行或乘坐的小车。','runners glide over snow.','冬季')],M('The children rode the sled across dry pavement on rubber wheels.','The children rode the sled down the snowy hill on its runners.','sled靠滑橇在雪冰上滑行，不是带轮车辆。','distinction'),[Q(1,'A sled is…','a small runner-equipped vehicle for snow or ice','a light horse-drawn carriage','a frying pan with a long handle','That is the source sense.','meaning'),Q(1,'Why pull a sled up a snowy hill?','To ride it back down over the snow','To use it as a skylight','To cut a slab of stone','The runners let the sled glide downhill.','context'),Q(1,'Which phrase is natural?','pull the sled up the hill','pull the sledly uphill to','a sled in the pull of hill','Up the hill describes the direction it is pulled.','grammar'),Q(1,'Which item is most likely a sled?','A small vehicle with runners used on snow','A flat pan used to fry eggs','A tool with a curved blade','Runners allow a sled to travel over snow and ice.','meaning')]);
P('sledge','Sledge is related to Dutch slee, the source of sled; in British English it names a snow vehicle, and it can also mean a heavy hammer.',[C('sledge.s1','冬季','The supply team travelled by sledge after snow covered the mountain road.','山路被雪覆盖后，补给队乘雪橇前行。','travel by sledge; pull a sledge over snow','名词，英式英语中指在雪上滑行的橇，也可指大锤。','snow vehicle carries supplies.','冬季')],M('The British travellers called their sledge a snow vehicle, but it had wheels and drove on dry roads.','The British travellers loaded the sledge and pulled it over the snow.','此处sledge是雪橇，不是轮式道路车辆。','meaning'),[Q(1,'In British English, a sledge is…','a sled used on snow','a small hand sieve','a pair of loose trousers','The source labels this as a British word for sled.','meaning'),Q(1,'How did the supply team travel after snow blocked the road?','By sledge over the snow','By skillet through the snow','By skylight across the mountain','The sledge carried supplies over snow.','context'),Q(1,'Which phrase is natural?','pull a sledge through the snow','pull a sledge through snowly','a sledge on the pulling of snow','Through the snow describes its route.','grammar'),Q(1,'Sledge can also refer to…','a sledgehammer','a short nap','a radio signal','The source entry includes the heavy hammer sense.','meaning')]);
P('sleek','Sleek is an old word of uncertain deeper origin; it describes a smooth, shiny surface or a modern, elegant, advanced-looking design.',[C('sleek.s1','家居','The polished wood gave the table a sleek finish that was smooth to the touch.','打磨后的木头让桌面表层光滑发亮。','a sleek surface/finish; sleek and polished','形容词，指表面平滑、发亮且没有毛糙或松散部分。','polished wood is smooth.','家居'),C('sleek.s2','设计','The new phone has a sleek high-tech look with a narrow screen and metal edges.','这款新手机外观简洁优雅，配有窄屏和金属边框。','a sleek design/profile; sleek modern look','形容词也指外形现代、优雅且显得先进。','modern device appearance.','设计')],M('The new phone looked sleek even though its case was rough, dull, and covered in loose parts.','The new phone looked sleek, with a smooth polished surface and a clean modern design.','粗糙暗淡且零件松动与sleek相反。','meaning'),[Q(1,'A sleek table finish is…','smooth and shiny','rough and covered in loose parts','a quick comic performance','The first sense describes a polished surface.','meaning'),Q(2,'A sleek phone design looks…','modern, elegant, and advanced','old-fashioned and poorly assembled','like a sledge','That is the second source sense.','context'),Q(1,'Which phrase is natural?','a sleek modern profile','a sleekly modern profile of','a sleekness phone profile','Sleek is an adjective modifying profile.','grammar'),Q(1,'Which object most clearly looks sleek?','A smooth, polished device with a clean modern shape','A rough box with loose splinters','A torn slab of slate','The adjective combines smoothness and elegant design.','meaning')]);
P('sleep','Sleep is from Old English slǣpan, a Germanic verb; it means the natural unconscious rest state, that state or a period of it, or have beds for a stated number of people.',[C('sleep.s1','健康','I slept for eight hours before the early train left.','早班火车出发前，我睡了八个小时。','sleep for + period; sleep well/badly','动词，指进入心智不清醒、身体通常静止的自然休息状态。','person rests overnight.','健康'),C('sleep.s2','健康','The baby had a short sleep after lunch and woke up cheerful.','宝宝午饭后睡了一小会儿，醒来时很开心。','have/get a sleep; a good night’s sleep','名词，指睡眠状态或一段睡眠时间。','rest period.','健康'),C('sleep.s3','住宿','The cabin sleeps six, with two beds in each of its three rooms.','这间小木屋有三间房，每间两张床，可住六个人。','a room/cabin sleeps + number','动词，指有足够床位供特定人数过夜。','capacity specified.','住宿')],M('The cabin sleeps six, meaning all six guests must sleep standing outside with no beds.','The cabin sleeps six because it has enough beds for six overnight guests.','sleeps six表示可容纳六人过夜，不是没有床位。','meaning'),[Q(1,'To sleep for eight hours is to…','rest in the natural unconscious state','stay awake for eight hours','take a sledgehammer to a bed','The first sense is the verb “rest.”','meaning'),Q(2,'A short sleep after lunch is…','a period of rest','a large mountain building','a light snow vehicle','Sleep can be a noun for a rest period.','context'),Q(3,'The cabin sleeps six means…','it has beds for six people','six people must remain awake','it is only six feet wide','The third sense describes accommodation capacity.','meaning'),Q(1,'Which phrase is natural?','sleep for eight hours','sleep at eight hoursly','sleeping for a sleeped eight','For introduces duration.','grammar')]);
P('sleeper','Sleeper is formed from sleep + -er; it means someone who is sleeping or a train compartment fitted with beds.',[C('sleeper.s1','交通','We booked a sleeper on the night train so the children could lie down.','我们订了夜班火车的卧铺车厢，好让孩子们躺下休息。','book/travel in a sleeper; a sleeper compartment','名词，指正在睡觉的人或火车卧铺车厢。','train berth provides beds.','交通')],M('They booked a sleeper on the night train, but the compartment had no beds and only seats.','They booked a sleeper on the night train, a compartment fitted with beds.','无床座席车厢不是卧铺车厢。','meaning'),[Q(1,'A sleeper on a train is…','a compartment with beds','a dining car with skillets','a glass roof window','The source entry includes a train compartment with beds.','meaning'),Q(1,'Why book a sleeper for children on a night train?','They can lie down and sleep during the trip.','They need to ski inside the carriage.','They want to inspect the skyline.','Beds make overnight travel more comfortable.','context'),Q(1,'Which phrase is natural?','book a sleeper on the train','book a sleeperly to train','a sleeper booking of sleeping','On the train locates the compartment.','grammar'),Q(1,'Sleeper is formed from sleep plus…','-er','-ness','-ful','The suffix forms a noun for a person or thing associated with sleep.','word-formation')]);
P('sleepiness','Sleepiness is formed from sleepy + -ness; it names drowsiness or the desire to sleep.',[C('sleepiness.s1','安全','Sleepiness at the wheel causes many night accidents, so drivers should stop to rest.','开车时犯困会造成许多夜间事故，因此司机应该停车休息。','feel sleepiness; sleepiness at the wheel','名词，指困倦、想要睡觉的状态。','drowsiness creates driving risk.','安全')],M('Sleepiness at the wheel made the driver more alert and less likely to close their eyes.','Sleepiness at the wheel made the driver drowsy and more likely to lose concentration.','困倦会降低警觉性，不会让人更清醒。','meaning'),[Q(1,'Sleepiness is…','drowsiness or a desire to sleep','a sudden large increase','a type of snow vehicle','The noun names the state of feeling sleepy.','meaning'),Q(1,'Why is sleepiness at the wheel dangerous?','It can reduce attention while driving.','It helps drivers see better.','It turns a car into a sledge.','Drowsiness increases accident risk.','context'),Q(1,'Which phrase is natural?','sleepiness at the wheel','sleepy at the wheelness','sleepiness to wheeled at','At the wheel means while driving.','grammar'),Q(1,'The suffix -ness in sleepiness forms…','a noun naming a state','a past-tense verb','a vehicle name','It names the quality or condition of being sleepy.','word-formation')]);
P('sleeping','Sleeping is formed from sleep + -ing; it names the natural rest period or describes someone, an animal, or a place where somebody is asleep.',[C('sleeping.s1','健康','An hour of sleeping after lunch helped her focus in the afternoon.','午饭后睡一小时让她下午更能集中注意力。','a period of sleeping; sleeping pattern','名词，指身体和大脑休息、双眼闭合的自然状态。','rest improves focus.','健康'),C('sleeping.s2','日常','The room stayed quiet except for a sleeping baby in the cot.','除了婴儿床里熟睡的宝宝，房间里一片安静。','a sleeping child/animal; sleeping area','形容词，表示人或动物正在睡觉，或某处有人睡觉。','baby is asleep.','日常')],M('The sleeping baby was awake, crying, and playing loudly in the cot.','The sleeping baby was asleep and quiet in the cot.','大声哭闹表示醒着，而非正在睡觉。','meaning'),[Q(1,'An hour of sleeping is…','a period of natural rest','a period of loud exercise','a short comic play','Sleeping as a noun refers to rest.','meaning'),Q(2,'A sleeping baby is…','a baby who is asleep','a baby who is actively crying','a baby who is steering a boat','The adjective sense describes someone asleep.','context'),Q(1,'Which phrase is natural?','a sleeping child','a sleepingly child','a sleeping of child','Sleeping is an adjective before child.','grammar'),Q(1,'Sleeping is formed from sleep plus…','-ing','-er','-ish','The suffix creates the noun/adjective form.','word-formation')]);
P('sleepy','Sleepy is formed from sleep + -y; it describes someone ready to fall asleep or a place that is quiet with little activity.',[C('sleepy.s1','健康','The children were sleepy after the long ride and fell asleep before dinner.','长途乘车后，孩子们困得晚饭前就睡着了。','feel/look sleepy; sleepy after + activity','形容词，指想睡觉或显出睡意。','children drowsy.','健康'),C('sleepy.s2','城镇','We spent a week in a sleepy coastal town where most shops closed early.','我们在一座安静冷清的海滨小镇住了一周，大多数商店很早就关门。','a sleepy town/village; a sleepy backwater','形容词也指地方安静、活动很少。','quiet town with little business.','城镇')],M('The children were sleepy after the ride, running around energetically until midnight.','The children were sleepy after the ride and nodded off before dinner.','精力充沛地跑到午夜不是显出睡意。','meaning'),[Q(1,'A sleepy child is…','ready to fall asleep','wide awake and energetic','a person directing a ship','The first sense means drowsy.','meaning'),Q(2,'A sleepy coastal town has…','little activity and quiet streets','constant crowds and nonstop nightlife','a tall skyline of skyscrapers','The second sense describes a quiet place.','context'),Q(1,'Which phrase is natural?','feel sleepy after the journey','feel sleepinessly after journey','a sleepy to feel journey','Feel sleepy is the standard construction.','grammar'),Q(2,'Which sentence uses sleepy for a place?','The sleepy village had one small shop.','The sleepy child yawned.','She slept for eight hours.','The first describes low activity in a town.','meaning')]);
P('sleet','Sleet is an old weather word of uncertain deeper origin; it names rain falling as small ice pieces or snow melting into rain before reaching the ground, and the weather event itself.',[C('sleet.s1','天气','A cold wind brought sleet by evening, coating the steps with tiny ice pellets.','傍晚冷风带来了雨夹雪，台阶上覆着细小冰粒。','falling sleet; sleet and freezing rain','名词，指雨落成小冰粒或雪在落地前化成雨的现象。','ice pellets accumulate.','天气'),C('sleet.s2','天气','It sleeted through the morning, so the drivers reduced their speed.','整个上午都在下雨夹雪，因此司机们减慢了车速。','it sleets; it sleeted all morning','动词，常以it作主语，表示下起雨夹雪。','precipitation affects roads.','天气')],M('It sleeted all morning, but warm dry sunshine left the roads completely clear.','It sleeted all morning, leaving icy pellets and slippery roads.','雨夹雪与温暖干燥晴天相反。','meaning'),[Q(1,'Sleet is precipitation that…','falls as small pieces of ice or partly melted snow','is only warm dry sunshine','forms a thick concrete slab','The source describes ice pellets or melting snow.','meaning'),Q(2,'Why did drivers slow down when it sleeted?','The icy precipitation made roads slippery.','The sky was perfectly clear.','They were taking a siesta.','Sleet can create dangerous road conditions.','context'),Q(1,'Which sentence uses sleet as a verb?','It sleeted through the morning.','The sleet covered the road.','A sleet of stones hit the roof.','The verb is commonly used with it as the subject.','grammar'),Q(1,'The deeper origin of sleet is…','uncertain','a certain Latin word for signature','a compound of ski and light','No precise earlier derivation is asserted.','word-formation')]);
P('sleeve','Sleeve is from Old English slīef, a Germanic word; it names the part of a garment covering the arm, a paper record cover, or a tube fitted over a machine part.',[C('sleeve.s1','服装','The sleeves of his coat were too long and covered his hands.','他外套的袖子太长，盖住了双手。','shirt/coat sleeve; roll up one’s sleeves','名词，指衬衫、外套或连衣裙上覆盖手臂的部分。','fabric covers arms.','服装'),C('sleeve.s2','物品','The album’s title was printed on the paper sleeve around the record.','专辑名称印在唱片外面的纸套上。','a record/paper sleeve; slide something into a sleeve','名词也指唱片封套或套在机器部件外的管子。','paper cover surrounds record.','物品')],M('The coat’s sleeve covered his arm, but it was the outer paper cover around the vinyl record.','The coat’s sleeve covered his arm from shoulder toward the wrist.','此处coat sleeve是衣袖，不是唱片纸套。','distinction'),[Q(1,'A coat sleeve is…','the part that covers the arm','the part that covers the head','a strip of cloth for shoes','Sleeve sense 1 is part of a garment.','meaning'),Q(2,'A record sleeve is…','a paper cover around the record','a long metal pin for grilling','a roof opening with glass','The second sense includes a record cover.','context'),Q(1,'Which phrase is natural?','roll up your sleeves','roll up the sleevefully','sleeve your roll to up','Roll up one’s sleeves is a common expression.','collocation'),Q(2,'Which object might slide into a sleeve?','A vinyl record into its paper cover','A mountain into a sledge','A skillet into soup','The paper cover is the second sense.','meaning')]);
P('sleigh','Sleigh is borrowed from Dutch slee, related to sled; it is a light open carriage on runners, usually drawn by a horse over snow.',[C('sleigh.s1','冬季','A horse-drawn sleigh carried the guests across the frozen lake.','一辆马拉雪橇载着客人穿过结冰的湖面。','a horse-drawn sleigh; ride in a sleigh','名词，指装有滑橇、通常由马拉着在雪上行驶的轻便敞篷车。','carriage travels over snow.','冬季')],M('The sleigh carried guests across the lake on rubber wheels over warm dry pavement.','The sleigh carried guests across the frozen lake on runners over the snow.','此处sleigh以滑橇在雪冰上行驶，不是轮式汽车。','distinction'),[Q(1,'A sleigh is…','a light carriage on runners for snow','a metal frying pan','a small bed compartment on a train','That is the source definition.','meaning'),Q(1,'How did the guests cross the frozen lake?','In a horse-drawn sleigh','In a skillet','On a sidewalk bus','The sleigh is a snow carriage.','context'),Q(1,'Which phrase is natural?','ride in a sleigh','ride a sleighly to','a sleigh in ride the','In is used with riding inside the carriage.','grammar'),Q(1,'Sleigh is related to the Dutch word…','slee','slæc','slēan','The snow vehicle word came from Dutch.','word-formation')]);
P('sleight','Sleight comes from Middle English for dexterity or cleverness, with roots in an old Scandinavian word; it now most often appears in “sleight of hand.”',[C('sleight.s1','魔术','The magician distracted the audience with sleight of hand while hiding the coin.','魔术师用手法转移观众注意力，同时藏起了硬币。','sleight of hand; perform a sleight','名词，指灵巧或骗人的手法。','dexterous trick conceals coin.','魔术')],M('The magician used sleight of hand by showing every movement slowly and revealing the coin’s location.','The magician used sleight of hand to hide the coin through a quick, deceptive movement.','公开展示并揭示位置不算欺骗性手法。','meaning'),[Q(1,'Sleight of hand is…','dexterity used to perform a cunning trick','a written name on a contract','a snowy carriage','The source sense is skillful or deceptive handling.','meaning'),Q(1,'Why use sleight of hand in a magic trick?','To conceal a movement or object from the audience','To make the action easy to inspect','To skate across the stage','The trick depends on dexterity and misdirection.','context'),Q(1,'Which phrase is standard?','sleight of hand','slight of hand','sleighted handly','The established phrase uses sleight, not slight.','spelling'),Q(1,'Sleight is closest in meaning to…','dexterity','sleepiness','sleet','The word refers to skill or a cunning trick.','meaning')]);
P('slender','Slender came through Middle English, with its deeper source uncertain; it means thin in a graceful way or small in amount, often barely enough.',[C('slender.s1','建筑','The footbridge rests on slender steel columns that make the structure look light.','人行桥由纤细的钢柱支撑，使结构看起来轻巧。','slender figure/column; a slender build','形容词，指细而好看，不粗重。','narrow supports look light.','建筑'),C('slender.s2','数量','The proposal passed by a slender majority of just three votes.','这项提案只以三票的微弱多数通过。','a slender majority/chance; a slender margin','形容词也表示数量很少，常常勉强够用。','margin barely sufficient.','数量')],M('The proposal passed by a slender majority of 400 votes in a 401-vote assembly.','The proposal passed by a slender majority of three votes.','四百票对一票不是微弱多数。','meaning'),[Q(1,'A slender column is…','thin and graceful rather than thick or heavy','very wide and bulky','a cooking skewer','Slender sense 1 describes a thin form.','meaning'),Q(2,'A slender majority of three votes is…','a small margin that barely passes','a huge majority','a unanimous vote','The second sense means small in amount.','context'),Q(1,'Which phrase is natural?','a slender steel column','a slenderly steel column','a steel slenderness','Slender is an adjective before column.','grammar'),Q(2,'Which is a slender chance?','A small but real chance of success','A certainty of success','No possibility at all','Slender can describe a small chance.','meaning')]);
P('slenderize','Slenderize is formed from slender + -ize; it means cause a body, garment, or shape to look thinner.',[C('slenderize.s1','服装','The jacket’s angled seams are designed to slenderize the waist visually.','这件夹克的斜向接缝经过设计，能在视觉上显得腰身更纤细。','slenderize a figure/waist; a cut that slenderizes','动词，指使身体、衣服或外形看起来更瘦、更苗条。','seams create visual effect.','服装')],M('The jacket was designed to slenderize the waist, making it look much wider and heavier.','The jacket was designed to slenderize the waist, making it look narrower.','显得更宽更重与显瘦相反。','meaning'),[Q(1,'A jacket that slenderizes the waist…','makes it look thinner','makes it look wider','covers it with a sleeve','Slenderize means make something appear more slender.','meaning'),Q(1,'How do angled seams slenderize a garment?','They create a visual impression of a narrower waist.','They add bulk across the waist.','They turn the jacket into a sleigh.','The effect is visual shaping.','context'),Q(1,'Which phrase is natural?','a cut that slenderizes the figure','a slenderize cutly the figure','a figure slenderizingly of cut','Slenderizes is a transitive verb here.','grammar'),Q(1,'Slenderize is formed from slender plus…','-ize','-ness','-er','The suffix -ize forms a verb meaning make or render.','word-formation')]);
P('slice','Slice is of uncertain deeper origin; it names a thin flat piece of food or a share of something, and as a verb means cut food into thin pieces.',[C('slice.s1','饮食','Would you like another slice of bread with your soup?','你想再要一片面包配汤吗？','a slice of bread/cake; cut into slices','名词，指从面包、蛋糕或肉上切下的薄而平的一块。','thin piece offered.','饮食'),C('slice.s2','商业','The company hopes to win a larger slice of the market next year.','公司希望明年获得更大的市场份额。','a slice of + market/profit/time','名词也指更大事物中的一部分或一份。','share of market.','商业'),C('slice.s3','烹饪','Slice the tomatoes thinly before arranging them on the plate.','把西红柿切成薄片，再摆到盘子里。','slice something thinly; slice through + food','动词，指把食物切成薄而平的片。','tomatoes cut flat.','烹饪')],M('She sliced the tomatoes by leaving them whole and placing them on the plate.','She sliced the tomatoes into thin flat pieces before plating them.','完整不切的西红柿不是薄片。','meaning'),[Q(1,'A slice of bread is…','a thin flat piece cut from the loaf','the whole loaf','a window cover','The first sense is a food portion.','meaning'),Q(2,'A slice of the market is…','a share of the larger market','a piece of bread','a narrow strip of stone','The second sense means part or share.','context'),Q(3,'To slice tomatoes is to…','cut them into thin flat pieces','shove them into a pan whole','skim fat off them','The verb sense is thin cutting.','meaning'),Q(1,'Which phrase is natural?','a slice of cake','a slicedly cake of','slice cake a to','Of introduces the food cut into a piece.','grammar')]);
P('slick','Slick is an old word of Germanic origin; it describes a smooth wet or polished surface, a clever but possibly insincere manner, or a thin floating layer of oil.',[C('slick.s1','安全','The floor was slick with rainwater, so the cleaner placed warning signs nearby.','地板上有雨水很滑，因此清洁人员在旁边放了警示牌。','slick with + liquid; a slick surface','形容词，指湿滑或打磨发亮、难以抓握或站稳。','water makes floor slippery.','安全'),C('slick.s2','交流','He gave a slick answer that sounded polished but did not address the question.','他的回答听起来圆滑成熟，却没有回应问题。','a slick answer/presentation; slick and persuasive','形容词也指巧妙顺滑但未必真诚可靠。','polished reply avoids issue.','交流'),C('slick.s3','环境','Workers cleaned a thin slick of fuel from the harbour surface.','工人清理了港湾水面上的一层薄薄燃油。','an oil/fuel slick; a slick on the water','名词，指漂在水面上的一薄层油或液体。','fuel floats on water.','环境')],M('The floor was slick with water, so everyone walked safely without any risk of slipping.','The floor was slick with water, so people walked carefully to avoid slipping.','湿滑地面会增加滑倒风险。','meaning'),[Q(1,'A slick floor is…','smooth or wet and hard to stand on','rough and dry with strong grip','a flat stone slab','The first sense concerns slippery surfaces.','meaning'),Q(2,'A slick answer may be…','smoothly delivered but not fully sincere or relevant','plain and completely direct','a high-pitched cry','This sense can imply polished but unreliable speech.','context'),Q(3,'An oil slick is…','a thin layer of oil floating on water','a thick stone roof','a pair of loose trousers','The noun sense refers to surface oil.','meaning'),Q(1,'Which phrase is natural?','a slick of fuel on the water','a slickly of fuel watering','fuel slick on of the','Of describes the floating layer.','grammar')]);
P('slide','Slide is from Old English slīdan “slip, glide,” a Germanic verb; it means move smoothly along a surface, gradually worsen, or name a playground structure, projected image, or microscope plate.',[C('slide.s1','日常','The drawer slides open easily because the runners are clean and straight.','抽屉滑轨干净笔直，因此很容易滑开。','slide along/across; slide something open','动词，指沿表面平滑移动或使某物滑动。','drawer moves on runners.','日常'),C('slide.s2','社会','After the talks broke down, relations slid into open argument.','谈判破裂后，双方关系逐渐陷入公开争吵。','slide into + worse state; a slide in + condition','动词也指逐渐变成更糟的状态。','relations deteriorate gradually.','社会'),C('slide.s3','教学','The next slide shows the results from the winter study.','下一张幻灯片展示了冬季研究的结果。','a presentation slide; show a slide','名词也指儿童滑梯、投影图片或显微镜玻片。','screen image displays data.','教学')],M('The talks slid into agreement, becoming more friendly and less hostile.','The talks slid into argument as the participants became more hostile.','逐渐达成和解不是变得更糟。','meaning'),[Q(1,'A drawer that slides open…','moves smoothly along its runners','falls apart into slabs','shutters a store','Slide sense 1 is smooth movement.','meaning'),Q(2,'Relations slid into argument means they…','gradually became worse','improved immediately','were photographed','The second sense describes gradual deterioration.','context'),Q(3,'A slide in a presentation is…','an image shown on a screen','a window sleeve','a snow carriage','This is one of the noun senses.','meaning'),Q(1,'Which phrase is natural?','slide the drawer open','slide the drawer openedly','a sliding drawer to open of','The verb can be followed by an object and result state.','grammar')]);
P('slider','Slider is formed from slide + -er; it names a component or screen control that moves along a groove or bar.',[C('slider.s1','科技','Drag the slider to the right to increase the speaker volume.','向右拖动滑块以调高扬声器音量。','move/drag a slider; a volume slider','名词，指沿槽或轨道移动的零件，或界面上可拖动的滑杆。','control moves along bar.','科技')],M('Drag the slider to change the volume, but it is a fixed button that cannot move along any track.','Drag the slider along its bar to change the volume.','固定不可移动的按钮不是滑杆。','meaning'),[Q(1,'A volume slider is…','a control that moves along a bar','a fixed label with no movement','a snow vehicle','The source sense is a moving control.','meaning'),Q(1,'How do you raise the speaker volume?','Drag the slider to the right.','Shred the audio file.','Skulk behind the speaker.','The slider changes the setting as it moves.','context'),Q(1,'Which phrase is natural?','drag the slider to the right','drag the slidery to righting','a slider of drag right to the','To the right gives the direction of movement.','grammar'),Q(1,'Slider is formed from slide plus…','-er','-ous','-age','The suffix forms a noun for a moving component.','word-formation')]);
P('slight','Slight is an old word with Germanic roots; it means small or not serious, thin and delicate in build, or treat someone as if they do not matter.',[C('slight.s1','健康','The patient felt only a slight headache after the long flight.','长途飞行后，患者只感到轻微头痛。','a slight problem/increase; a slight headache','形容词，指数量或重要性很小、不严重。','symptom is minor.','健康'),C('slight.s2','外观','He was a slight young man with narrow shoulders and a delicate build.','他是个身材瘦削、肩膀窄、体格单薄的年轻人。','a slight build/figure; slight and delicate','形容词也指身材瘦而单薄。','body build is thin.','外观'),C('slight.s3','社交','She felt slighted when the hosts forgot to introduce her to the guests.','主人忘了把她介绍给客人时，她觉得自己受到了冷落。','slight someone; feel slighted by + action','动词，指把某人当成不重要来对待，使其感到受冷落。','omission signals disregard.','社交')],M('She felt slighted because the hosts warmly welcomed her and carefully introduced her to everyone.','She felt slighted because the hosts ignored her and did not introduce her to anyone.','受到热情欢迎和介绍不是被冷落。','distinction'),[Q(1,'A slight headache is…','small and not serious','severe and dangerous','a fast moving vehicle','The first sense means minor.','meaning'),Q(2,'A slight young man has…','a thin and delicate build','a broad and heavy build','a large share of the market','The second sense concerns physique.','context'),Q(3,'She felt slighted means she felt…','treated as if she did not matter','physically shortened','pleased by an introduction','The verb means treat someone dismissively.','meaning'),Q(1,'Which phrase is natural?','a slight increase in cost','a slightly increase in cost','a slightness increase of cost','Slight is an adjective modifying increase.','grammar')]);
})();
